    private async Task RefreshAsync()
    {
        if (_refreshing)
            return;

        _refreshing = true;

        try
        {
            var elapsed = Stopwatch.StartNew();
            var captured = await Task.Run(() => _collector.Capture());
            if (_windowClosed) return;
            // Metadata refresh must never overwrite recent fast CPU with a 15/45-second sample.
            var snapshots = captured.Select(p => RecentCpu(p.Pid) is { } cpu && cpu.Matches(p)
                ? cpu.Apply(p) : LiveCpuSample.Unavailable(p))
                .Select(p => RecentMemory(p.Pid) is { } memory ? memory.Apply(p) : p)
                .Select(p => RecentNetwork(p.Pid) is { } net ? net.Apply(p) : p).ToArray();
            elapsed.Stop();
            TrackMemoryHistory(snapshots);

            var livePids = snapshots.Select(x => x.Pid).ToHashSet();
            foreach (var deadPid in _insightCache.Keys.Where(pid => !livePids.Contains(pid)).ToArray())
                _insightCache.Remove(deadPid);

            foreach (var deadPid in _deepCache.Keys.Where(pid => !livePids.Contains(pid)).ToArray())
                _deepCache.Remove(deadPid);

            foreach (var deadPid in _cpuHistory.Keys.Where(pid => !livePids.Contains(pid)).ToArray())
            {
                _cpuHistory.Remove(deadPid);
                _cpuHistoryStarts.Remove(deadPid);
            }
            foreach (var deadPid in _memoryHistory.Keys.Where(pid => !livePids.Contains(pid)).ToArray())
                _memoryHistory.Remove(deadPid);

            foreach (var deadPid in _progressSamples.Keys.Where(pid => !livePids.Contains(pid)).ToArray())
                _progressSamples.Remove(deadPid);

            _allRows = snapshots
                .Select(BuildRow)
                .ToList();

            ProcessCountText.Text = _allRows.Count.ToString();
            LogicalCpuText.Text = Environment.ProcessorCount.ToString();
            var sysCpu = _collector.LatestCpuTelemetry;
            // Cheap GlobalMemoryStatusEx sample: do not scan a second time to
            // decide how often to refresh. If unavailable, keep the normal interval.
            double? usedRam = null;
            try { usedRam = WindowsPhysicalMemoryReader.Read().UsedPercent; }
            catch (Exception) { /* No invented memory-pressure reading. */ }
            _timer.Interval = MonitorRefreshPolicy.ForProcesses(
                sysCpu.HasSample ? sysCpu.BusyPercent : null, usedRam);
            if (elapsed.Elapsed >= TimeSpan.FromSeconds(1) &&
                DateTime.UtcNow - _lastSlowRefreshLoggedUtc > TimeSpan.FromMinutes(2))
            {
                AppDiagnostics.Record(global::ProcessLens.Core.SysPulseLocalization.Capture($"Raccolta processi lenta: {(snapshots.Length)} processi, ") +
                    global::ProcessLens.Core.SysPulseLocalization.Capture($"durata {(elapsed.ElapsedMilliseconds)} ms; intervallo successivo {(_timer.Interval.TotalSeconds):F0} s."));
                _lastSlowRefreshLoggedUtc = DateTime.UtcNow;
            }
            // IMPORTANT: use the selection that exists NOW, after the async capture.
            // The user may have clicked another process while Capture() was running.
            if (!_servicesMode && !_guardianMode && !_memoryMode && !_networkMode && !_systemMode)
                ApplyFilter(_selectedPid, preserveScroll: true, allowInitialSelection: !_initialSelectionDone);
        }
        finally
        {
            _refreshing = false;
        }
    }

    internal void SetDashboardWindowVisibility(bool active)
    {
        if (_windowClosed) return;
        if (active)
        {
            if (_monitoringEnabled) { _cpuTimer.Start(); _ = RefreshCpuAsync(); }
        }
        else
        {
            _cpuTimer.Stop();
            _cpuGeneration++;
            _cpuHistory.Clear();
            _cpuHistoryStarts.Clear();
            _resetCpu = true;
            if (!_cpuRefreshing) _liveCpu.Reset(); // No worker can be using these buffers here.
            _latestCpu = new Dictionary<int, LiveCpuSample>();
            _selfResourceReport = string.Empty;
            CopySelfResourcesButton.IsEnabled = false;
            SelfResourcesText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Risorse GUI: campionamento sospeso mentre la finestra è ridotta.");
            ApplyLiveMemorySamples(new Dictionary<int, LiveMemorySample>());
            ApplyLiveNetworkSamples(new Dictionary<int, LiveNetworkSample>());
            foreach (var row in _allRows) row.UpdateCpu(null);
            SystemCpuText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Sospeso");
            SystemCpuAverageText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("N/D");
            SystemRamText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Sospeso");
            SystemRamText.ToolTip = global::ProcessLens.Core.SysPulseLocalization.Literal("Campionamento RAM sospeso mentre la finestra è ridotta.");
        }
        GuardianDashboard?.SetActive(active && _guardianMode);
        MemoryDashboard?.SetActive(active && _memoryMode);
        NetworkDevices?.SetActive(active && _networkMode);
        SystemProcesses?.SetActive(active && _systemMode);
    }


    private LiveCpuSample? RecentCpu(int pid)
    {
        if (!_latestCpu.TryGetValue(pid, out var sample)) return null;
        double age = Stopwatch.GetTimestamp() / (double)Stopwatch.Frequency - sample.CapturedAtMonotonicSeconds;
        return age is >= 0 and <= CpuIntervalTracker.MaximumGapSeconds ? sample : null;
    }

    private LiveMemorySample? RecentMemory(int pid) =>
        _latestMemory.TryGetValue(pid, out var sample) &&
        sample.IsFresh(Stopwatch.GetTimestamp() / (double)Stopwatch.Frequency) ? sample : null;

    private LiveNetworkSample? RecentNetwork(int pid) =>
        _latestNetwork.TryGetValue(pid, out var sample) &&
        sample.IsFresh(Stopwatch.GetTimestamp() / (double)Stopwatch.Frequency) ? sample : null;

    internal void ApplyLiveMemorySamples(IReadOnlyDictionary<int, LiveMemorySample> samples)
    {
        Dispatcher.VerifyAccess();
        _latestMemory = samples;
        foreach (var row in _allRows) row.UpdateMemory(RecentMemory(row.Pid));
        TrackMemoryHistory(_allRows.Select(r => r.Process).ToArray());
        foreach (var group in _processGroups) group.Refresh();
        if (_currentDetailRow is { } detail && _selectedPid == detail.Pid)
        {
            if (!_allRows.Contains(detail)) detail.UpdateMemory(RecentMemory(detail.Pid));
            RefreshMemoryDetails(detail);
        }
    }

    internal void ApplyLiveNetworkSamples(IReadOnlyDictionary<int, LiveNetworkSample> samples)
    {
        Dispatcher.VerifyAccess();
        _latestNetwork = samples;
        foreach (var row in _allRows) row.UpdateNetwork(RecentNetwork(row.Pid));
        foreach (var group in _processGroups) group.Refresh();
        if (_currentDetailRow is { } detail && _selectedPid == detail.Pid)
        {
            if (!_allRows.Contains(detail)) detail.UpdateNetwork(RecentNetwork(detail.Pid));
            DetailNetworkStateText.Text = ProcessNetworkPresentation.DescribeEndpointOwners(detail.Process);
        }
    }

    private static SystemMemoryEvidence? ReadHeaderMemory()
    {
        // One small system counter read; no per-process inventory or retained history.
        // A RAM read failure must not discard a valid CPU sample.
        try
        {
            var memory = WindowsPhysicalMemoryReader.Read();
            return new SystemMemoryEvidence(memory.TotalBytes, memory.AvailableBytes);
        }
        catch (Exception) { return null; }
    }

    internal void UpdateSystemRam(SystemMemoryEvidence? memory)
    {
        SystemRamText.Text = ProcessDisplayFormatter.SystemRam(memory?.TotalBytes, memory?.AvailableBytes);
        SystemRamText.ToolTip = SystemRamText.Text == global::ProcessLens.Core.SysPulseLocalization.Literal("N/D")
            ? global::ProcessLens.Core.SysPulseLocalization.Literal("RAM del sistema: lettura non disponibile.")
            : global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("RAM fisica in uso / totale utilizzabile da Windows. In uso = totale - disponibile (GlobalMemoryStatusEx). "),global::ProcessLens.Core.SysPulseLocalization.Literal("Non è la somma dei Working Set dei processi. Aggiornata con il campione CPU."));
    }

    private async Task RefreshCpuAsync()
    {
        if (_cpuRefreshing || _windowClosed || !IsVisible || WindowState == WindowState.Minimized) return;
        _cpuRefreshing = true;
        int generation = _cpuGeneration;
        bool reset = _resetCpu;
        _resetCpu = false;
        int[] pids = (!_servicesMode && !_guardianMode && !_memoryMode && !_networkMode && !_systemMode ? _allRows.Select(r => r.Pid) : Enumerable.Empty<int>())
            .Append(Environment.ProcessId).Distinct().ToArray();
        try
        {
            var result = await Task.Run(() =>
            {
                if (reset) _liveCpu.Reset();
                return (Cpu: _liveCpu.Capture(pids), Memory: WindowsSelfResources.Capture(), SystemMemory: ReadHeaderMemory());
            });
            if (_windowClosed || generation != _cpuGeneration || !IsVisible || WindowState == WindowState.Minimized)
            {
                _liveCpu.Reset(); // Worker has completed; release its obsolete sample buffers.
                _resetCpu = true;
                return;
            }
            using var detailUpdate = _detailViewport?.Begin();
            UpdateSystemRam(result.SystemMemory);
            _latestCpu = result.Cpu.Processes;
            foreach (var row in _allRows) row.UpdateCpu(RecentCpu(row.Pid));
            ApplyLiveMemorySamples(result.Cpu.Memory);
            ApplyLiveNetworkSamples(result.Cpu.Network);
            var liveSnapshots = _allRows.Select(r => r.Process).ToArray();
            TrackCpuHistory(liveSnapshots);
            if ((_sortMode == global::ProcessLens.Core.SysPulseLocalization.Literal("CPU") || _sortMode == global::ProcessLens.Core.SysPulseLocalization.Literal("Memoria") || _sortMode == global::ProcessLens.Core.SysPulseLocalization.Literal("Memory") || _sortMode == global::ProcessLens.Core.SysPulseLocalization.Literal("Rete") || _sortMode == global::ProcessLens.Core.SysPulseLocalization.Literal("Network")) && !_servicesMode && !_guardianMode && !_memoryMode && !_networkMode && !_systemMode && ProcessList.ItemsSource is not null)
            {
                _suppressSelectionEvents = true;
                try { RefreshLiveProcessOrder(); }
                finally { _suppressSelectionEvents = false; }
            }
            var sys = result.Cpu.System;
            string na = SysPulseLocalization.IsEnglish ? global::ProcessLens.Core.SysPulseLocalization.Literal("N/A") : global::ProcessLens.Core.SysPulseLocalization.Literal("N/D");
            LogicalCpuText.Text = sys.LogicalProcessors > 0 ? sys.LogicalProcessors.ToString() : na;
            SystemCpuText.Text = sys.HasSample ? ProcessDisplayFormatter.Percent(sys.BusyPercent) : na;
            SystemCpuAverageText.Text = sys.HasSample ? ProcessDisplayFormatter.Percent(sys.Average30Seconds) : na;
            SystemCpuText.ToolTip = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Tempo CPU occupato da GetSystemTimes / tempo trascorso monotono / CPU logiche. "),global::ProcessLens.Core.SysPulseLocalization.Capture($"Intervallo {(ProcessDisplayFormatter.Seconds(sys.SampleIntervalSeconds))}; ")),global::ProcessLens.Core.SysPulseLocalization.Capture($"PID con campione {(sys.ProcessesWithCpuSamples)}, senza campione {(sys.ProcessesWithoutCpuAccess)}. ")),global::ProcessLens.Core.SysPulseLocalization.Literal("Oltre 64 CPU logiche il totale sistema è N/D: GetSystemTimes copre un solo gruppo. ")),global::ProcessLens.Core.SysPulseLocalization.Literal("Confrontare stesso PID e colonna CPU temporale; la colonna CPU Utility usa una metrica diversa. Gli aggiornamenti delle due finestre non sono simultanei."));
            if (_currentDetailRow is { } detail && _selectedPid == detail.Pid)
            {
                detail.UpdateCpu(RecentCpu(detail.Pid));
                RefreshCpuDetails(detail);
                if (detail.Process.IsDeepInspected &&
                    !_networkPortsRefreshing &&
                    DateTime.UtcNow - _lastAutoNetworkPortsRefreshUtc >= TimeSpan.FromSeconds(5))
                {
                    _lastAutoNetworkPortsRefreshUtc = DateTime.UtcNow;
                    RefreshProcessPorts_Click(this, new RoutedEventArgs());
                }
            }
            var memory = result.Memory;
            string MiB(long? value) => value.HasValue ? global::ProcessLens.Core.SysPulseLocalization.Capture($"{(value.Value / 1048576d):F1} MiB") : na;
            var own = RecentCpu(Environment.ProcessId);
            string ownCpu = own?.Available == true ? ProcessDisplayFormatter.Percent(own.Percent) : na;
            SelfResourcesText.Text = SysPulseLocalization.IsEnglish
                ? global::ProcessLens.Core.SysPulseLocalization.Capture($"SysPulse GUI · PID {(memory.Pid)} · CPU {(ownCpu)} · Private WS {(MiB(memory.PrivateResident))} · Total WS {(MiB(memory.Resident))}")
                : global::ProcessLens.Core.SysPulseLocalization.Capture($"GUI ProcessLens · PID {(memory.Pid)} · CPU {(ownCpu)} · Working Set privato {(MiB(memory.PrivateResident))} · Working Set totale {(MiB(memory.Resident))}");
            _selfResourceReport = SelfResourcesText.Text + global::ProcessLens.Core.SysPulseLocalization.Literal("\nIntervallo CPU effettivo: ") +
                (own?.Available == true ? ProcessDisplayFormatter.Seconds(own.IntervalSeconds) : na) + global::ProcessLens.Core.SysPulseLocalization.Capture($"\nCommit privato: {(MiB(memory.PrivateCommit))}") +
                global::ProcessLens.Core.SysPulseLocalization.Capture($"\nCampione UTC: {(memory.CapturedUtc):O}\nVersione: ") +
                typeof(MainWindow).Assembly.GetCustomAttributes(typeof(System.Reflection.AssemblyInformationalVersionAttribute), false)
                    .OfType<System.Reflection.AssemblyInformationalVersionAttribute>().FirstOrDefault()?.InformationalVersion +
                global::ProcessLens.Core.SysPulseLocalization.Literal("\nSolo processo GUI; Guardian e MemoryAgent esclusi. Commit e RAM fisica sono contatori distinti.");
            SelfResourcesText.ToolTip = _selfResourceReport;
            CopySelfResourcesButton.IsEnabled = true;
        }
        catch (Exception ex)
        {
            _resetCpu = true;
            _latestCpu = new Dictionary<int, LiveCpuSample>();
            ApplyLiveMemorySamples(new Dictionary<int, LiveMemorySample>());
            ApplyLiveNetworkSamples(new Dictionary<int, LiveNetworkSample>());
            foreach (var row in _allRows) row.UpdateCpu(null);
            if (_currentDetailRow is { } failedDetail)
            {
                failedDetail.UpdateCpu(null);
                failedDetail.UpdateMemory(null);
                RefreshCpuDetails(failedDetail);
                RefreshMemoryDetails(failedDetail);
            }
            string naCatch = SysPulseLocalization.IsEnglish ? global::ProcessLens.Core.SysPulseLocalization.Literal("N/A") : global::ProcessLens.Core.SysPulseLocalization.Literal("N/D");
            SystemCpuText.Text = naCatch; SystemCpuAverageText.Text = naCatch;
            UpdateSystemRam(null);
            SelfResourcesText.Text = SysPulseLocalization.IsEnglish ? global::ProcessLens.Core.SysPulseLocalization.Literal("GUI resources: unavailable.") : global::ProcessLens.Core.SysPulseLocalization.Literal("Risorse GUI: lettura non disponibile.");
            _selfResourceReport = string.Empty;
            CopySelfResourcesButton.IsEnabled = false;
            AppDiagnostics.Record(global::ProcessLens.Core.SysPulseLocalization.Literal("Campionamento CPU/RAM rapido non riuscito"), ex);
        }
        finally { _cpuRefreshing = false; }
    }

