    private ProcessInsight GetCachedInsight(ProcessSnapshot process)
    {
        string key = process.SemanticIdentityKey;
        if (_insightCache.TryGetValue(process.Pid, out var cached) && cached.IdentityKey == key)
            return cached.Insight;

        var insight = _analyzer.Analyze(process);
        _insightCache[process.Pid] = (key, insight);
        return insight;
    }

    private ProcessRow BuildRow(ProcessSnapshot process)
    {
        if (_deepCache.TryGetValue(process.Pid, out var deep) && SameProcessLifetime(process, deep.StartTime))
        {
            var merged = MergeDynamicSnapshot(process, deep.Process);
            return new ProcessRow(merged, deep.Insight);
        }

        return new ProcessRow(process, GetCachedInsight(process));
    }

    private static bool SameProcessLifetime(ProcessSnapshot process, DateTime? startTime)
    {
        if (process.StartTime.HasValue && startTime.HasValue)
            return process.StartTime.Value == startTime.Value;
        return true;
    }

    private static ProcessSnapshot MergeDynamicSnapshot(ProcessSnapshot current, ProcessSnapshot deep) => deep with
    {
        ParentPid = current.ParentPid,
        ParentName = current.ParentName,
        AncestorNames = current.AncestorNames,
        ChildCount = current.ChildCount,
        SameNameChildCount = current.SameNameChildCount,
        ServiceNames = current.ServiceNames,
        ServiceDisplayNames = current.ServiceDisplayNames,
        AncestorDetails = current.AncestorDetails,
        CpuPercent = current.CpuPercent,
        CpuSampleAvailable = current.CpuSampleAvailable,
        CpuAverage30Seconds = current.CpuAverage30Seconds,
        CpuPeak30Seconds = current.CpuPeak30Seconds,
        CpuLogicalCoreEquivalent = current.CpuLogicalCoreEquivalent,
        CpuCumulativeSeconds = current.CpuCumulativeSeconds,
        CpuCumulativeAvailable = current.CpuCumulativeAvailable,
        CpuSampleIntervalSeconds = current.CpuSampleIntervalSeconds,
        WorkingSetBytes = current.WorkingSetBytes,
        WorkingSetAvailable = current.WorkingSetAvailable,
        PrivateWorkingSetBytes = current.PrivateWorkingSetBytes,
        PrivateWorkingSetAvailable = current.PrivateWorkingSetAvailable,
        PrivateBytes = current.PrivateBytes,
        PrivateCommitAvailable = current.PrivateCommitAvailable,
        MemorySampledAtMonotonicSeconds = current.MemorySampledAtMonotonicSeconds,
        MemorySampledUtc = current.MemorySampledUtc,
        NetworkBytesPerSecond = current.NetworkBytesPerSecond,
        NetworkSendBytesPerSecond = current.NetworkSendBytesPerSecond,
        NetworkReceiveBytesPerSecond = current.NetworkReceiveBytesPerSecond,
        NetworkBandwidthAvailable = current.NetworkBandwidthAvailable,
        NetworkLiveAvailable = current.NetworkLiveAvailable,
        NetworkSampledAtMonotonicSeconds = current.NetworkSampledAtMonotonicSeconds,
        ThreadCount = current.ThreadCount,
        HandleCount = current.HandleCount,
        IsCritical = current.IsCritical
    };

    private void ApplyFilter(int? selectedPid = null, bool preserveScroll = false, bool allowInitialSelection = false)
    {
        if (!preserveScroll) { _listViewport?.Cancel(); _detailViewport?.Cancel(); }
        using var listUpdate = preserveScroll ? _listViewport?.Begin() : null;
        using var detailUpdate = preserveScroll ? _detailViewport?.Begin() : null;
        bool holdOrder = preserveScroll && _listViewport?.HoldsOrder == true;
        var previousRows = _visibleRows.ToDictionary(x => x.Pid);
        for (int index = 0; index < _allRows.Count; index++)
        {
            var next = _allRows[index];
            if (previousRows.TryGetValue(next.Pid, out var old) && !ReferenceEquals(old, next) &&
                ProcessGrouping.IdentityMatches(old.Process, next.Process))
            { old.UpdateFrom(next); _allRows[index] = old; }
        }

        string search = SearchBox.Text.Trim();
        IEnumerable<ProcessRow> rows = _allRows;

        rows = _activeFilter switch
        {
            "App" => rows.Where(x => x.Category == global::ProcessLens.Core.SysPulseLocalization.Literal("Applicazioni")),
            "Sviluppo" => rows.Where(x => x.Category == global::ProcessLens.Core.SysPulseLocalization.Literal("Sviluppo")),
            "Windows" => rows.Where(x => x.Category == global::ProcessLens.Core.SysPulseLocalization.Literal("Windows")),
            "Background" => rows.Where(x => x.Category == global::ProcessLens.Core.SysPulseLocalization.Literal("Background")),
            "WSL" => rows.Where(x => x.Category == global::ProcessLens.Core.SysPulseLocalization.Literal("WSL")),
            _ => rows
        };

        if (!string.IsNullOrWhiteSpace(search))
        {
            rows = rows.Where(row => ProcessIdentitySearch.Matches(row.Process, search, row.FriendlyName) || WindowsHostReference.Matches(row.Process, search));
        }

        rows = ApplySort(rows);
        var visible = rows.ToList();
        foreach (var group in _processGroups) _groupExpansion[group.Key] = group.IsExpanded;
        var rowByPid = visible.ToDictionary(x => x.Pid);
        var allByPid = _allRows.ToDictionary(x => x.Pid);
        var families = ProcessGrouping.Build(_allRows.Select(x => x.Process).ToArray());
        bool regroup = false;
        var previousGroups = _processGroups.ToDictionary(x => x.Key);
        var groups = new List<ProcessGroupRow>();
        foreach (var family in families)
        {
            var members = family.Members.Where(x => rowByPid.ContainsKey(x.Pid)).Select(x => rowByPid[x.Pid]).ToArray();
            if (members.Length == 0) continue;
            string title = WindowsHostReference.ListTitle(allByPid[family.Root.Pid].Process, allByPid[family.Root.Pid].FriendlyName);
            if (!previousGroups.TryGetValue(family.Key, out var group))
                group = new ProcessGroupRow(family.Key, title, members, family.Members.Count)
                    { IsExpanded = _groupExpansion.GetValueOrDefault(family.Key) };
            else group.UpdateMembers(title, members, family.Members.Count);
            foreach (var member in members)
            {
                if (!ReferenceEquals(member.Group, group) && _visibleRows.Contains(member)) regroup = true;
                member.Group = group;
            }
            groups.Add(group);
        }
        _processGroups = groups;
        var liveKeys = families.Select(x => x.Key).ToHashSet();
        foreach (string key in _groupExpansion.Keys.Where(x => !liveKeys.Contains(x)).ToArray()) _groupExpansion.Remove(key);
        if (_groupExpansion.Count > 512) _groupExpansion.Clear();

        _suppressSelectionEvents = true;
        try
        {
            bool grouped = GroupApplicationsCheckBox.IsChecked == true;
            if (_groupedView != grouped)
            {
                ProcessList.ItemTemplate = (DataTemplate)FindResource(grouped ? global::ProcessLens.Core.SysPulseLocalization.Literal("ProcessMemberTemplate") : global::ProcessLens.Core.SysPulseLocalization.Literal("ProcessCardTemplate"));
                var processView = CollectionViewSource.GetDefaultView(ProcessList.ItemsSource);
                using (processView.DeferRefresh())
                {
                    processView.SortDescriptions.Clear();
                    processView.GroupDescriptions.Clear();
                    if (grouped) processView.GroupDescriptions.Add(new PropertyGroupDescription(nameof(ProcessRow.Group)));
                }
                _groupedView = grouped;
            }
            bool orderChanged = SynchronizeVisibleRows(visible, holdOrder);
            if (grouped && (regroup || orderChanged)) CollectionViewSource.GetDefaultView(ProcessList.ItemsSource).Refresh();
            bool en = SysPulseLocalization.IsEnglish;
            string filterLabel = _activeFilter switch
            {
                "Tutti" => en ? global::ProcessLens.Core.SysPulseLocalization.Literal("View: all processes") : global::ProcessLens.Core.SysPulseLocalization.Literal("Vista: tutti i processi"),
                "App" => en ? global::ProcessLens.Core.SysPulseLocalization.Literal("View: Apps") : global::ProcessLens.Core.SysPulseLocalization.Literal("Vista: App"),
                "Sviluppo" => en ? global::ProcessLens.Core.SysPulseLocalization.Literal("View: Dev") : global::ProcessLens.Core.SysPulseLocalization.Literal("Vista: Sviluppo"),
                _ => en ? global::ProcessLens.Core.SysPulseLocalization.Capture($"View: {(_activeFilter)}") : global::ProcessLens.Core.SysPulseLocalization.Capture($"Vista: {(_activeFilter)}")
            };
            VisibleCountText.Text = visible.Count.ToString();
