            if (search.Length > 0) CurrentFilterText.Text += visible.Count == 0
                ? global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat((en ? global::ProcessLens.Core.SysPulseLocalization.Literal(" · No results for «") : global::ProcessLens.Core.SysPulseLocalization.Literal(" · Nessun risultato per «")),search[..Math.Min(search.Length, 100)]),global::ProcessLens.Core.SysPulseLocalization.Literal("»"))
                : global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat((en ? global::ProcessLens.Core.SysPulseLocalization.Literal(" · Search: «") : global::ProcessLens.Core.SysPulseLocalization.Literal(" · Cerca: «")),search[..Math.Min(search.Length, 100)]),global::ProcessLens.Core.SysPulseLocalization.Literal("»"));
            ProcessRow? item = null;

            if (selectedPid is not null)
