    private void ProcessList_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (!IsLoaded || ProcessList is null) return;
        if (_suppressSelectionEvents)
            return;

        if (ProcessList.SelectedItem is not ProcessRow row)
        {
            _selectedPid = null;
            ClearDetails();
            return;
        }

        // Persist the user's choice independently from the ListView object instance.
        // Every refresh creates new ProcessRow objects, but the PID remains stable.
        _selectedPid = row.Pid;
        _initialSelectionDone = true;
        ClearQueryAnswer();
        ShowDetails(row);
        QueueDeepInspection(row);
    }

    // Build context menus after the ListViewItem has been constructed. Placing an
    // event-wired ContextMenu inside Style.Setter.Value (in Window.Resources)
    // caused a WPF BAML IComponentConnector cast failure at InitializeComponent:
    // ContextMenu was incorrectly connected to a generated Grid field.
    private void ProcessItem_Loaded(object sender, RoutedEventArgs e)
    {
        if (sender is not ListViewItem item || item.ContextMenu is not null)
            return;

        var menu = new ContextMenu();
        menu.Opened += ProcessContextMenu_Opened;
        item.ContextMenu = menu;
    }

    private void ProcessContextMenu_Opened(object sender, RoutedEventArgs e)
    {
        // Pin the row when the menu opens. RefreshAsync may rebuild the ListView
        // before the user presses a menu command; DataContext could then change.
        _contextMenuTarget = sender is ContextMenu { PlacementTarget: ListViewItem item }
            ? item.DataContext as ProcessRow
            : null;
        if (sender is not ContextMenu menu) return;
        menu.Items.Clear();
        var row = _contextMenuTarget;
        if (row is null) return;
        if (row.Process.ServiceNames.Count > 0)
        {
            var stop = new global::ProcessLens.App.LocalizedMenuItem{ Header = global::ProcessLens.Core.SysPulseLocalization.Literal("Arresta servizio Windows…") };
            stop.Click += StopHostedServiceMenuItem_Click;
            menu.Items.Add(stop);
        }
        else
        {
            var terminate = new global::ProcessLens.App.LocalizedMenuItem{ Header = global::ProcessLens.Core.SysPulseLocalization.Literal("Termina processo…") };
            terminate.Click += TerminateProcessMenuItem_Click;
            menu.Items.Add(terminate);
        }
        menu.Items.Add(new Separator());
        var copyPid = new global::ProcessLens.App.LocalizedMenuItem{ Header = global::ProcessLens.Core.SysPulseLocalization.Literal("Copia PID") };
        copyPid.Click += CopyPidMenuItem_Click;
        menu.Items.Add(copyPid);
    }

    private ProcessRow? MenuTargetRow(object sender)
    {
