    private async void TerminateProcessMenuItem_Click(object sender, RoutedEventArgs e)
    {
        var row = MenuTargetRow(sender);
        if (row is null || _terminationBusy)
            return;

        // Capture the row the user right-clicked; never act on whichever selection
        // a concurrent refresh happens to display later.
        var target = row.Process;
