        string confirmation = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Terminare in modo forzato SOLO questo processo?\n\n"),global::ProcessLens.Core.SysPulseLocalization.Capture($"{(row.FriendlyName)} ({(global::ProcessLens.Core.SysPulseLocalization.Opaque(target.Name))})\n")),global::ProcessLens.Core.SysPulseLocalization.Capture($"PID: {(target.Pid)}\nAvviato: {(start)}\n\n")),global::ProcessLens.Core.SysPulseLocalization.Literal("Eventuali documenti non salvati, operazioni Git, download o attività in corso potrebbero essere persi. ")),global::ProcessLens.Core.SysPulseLocalization.Literal("I processi figli non verranno terminati automaticamente.\n\nConfermi?"));

        if (MessageBox.Show(this,global::ProcessLens.Core.SysPulseLocalization.Render(confirmation),global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Literal("Conferma terminazione processo")),                MessageBoxButton.YesNo,MessageBoxImage.Warning,MessageBoxResult.No) != MessageBoxResult.Yes)
            return;

        try
        {
            _terminationBusy = true;
            _requestedExitWatch?.Dispose();
            var identity = ProcessExitIdentity.From(target.Pid, target.StartTime, target.Name);
            _requestedExitWatch = identity is null ? null : ProcessExitWatch.TryCreate(identity, ProcessExitObserved);
            var result = await Task.Run(() => new WindowsProcessTerminator().Terminate(target, Environment.ProcessId));
            if (_windowClosed) return;
            if (!result.Succeeded)
            {
                _requestedExitWatch?.Dispose();
                _requestedExitWatch = null;
                MessageBox.Show(this,global::ProcessLens.Core.SysPulseLocalization.Render(result.Message),global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Literal("Operazione annullata")),MessageBoxButton.OK,MessageBoxImage.Warning);
            }
            else if (identity is null || !_exitNotices.WasShown(identity))
                ShowProcessNotice(global::ProcessLens.Core.SysPulseLocalization.Literal("Esito richiesta"), result.Message);
            await RefreshAsync();
        }
        catch (Exception ex)
        {
            _requestedExitWatch?.Dispose();
            _requestedExitWatch = null;
            if (_windowClosed) return;
            MessageBox.Show(this,global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Capture($"Errore durante la verifica/terminazione: {(ex.Message)}")),global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Literal("Operazione non completata")),MessageBoxButton.OK,MessageBoxImage.Error);
        }
        finally { _terminationBusy = false; }
    }

    private void TrackSelectedProcessExit(ProcessRow row)
    {
        if (_windowClosed) return;
        var identity = ProcessExitIdentity.From(row.Pid, row.Process.StartTime, row.Process.Name);
        if (identity == _watchedSelectionIdentity) return;
        _selectedExitWatch?.Dispose();
        _watchedSelectionIdentity = identity;
        _selectedExitWatch = identity is null ? null : ProcessExitWatch.TryCreate(identity, ProcessExitObserved);
    }

    private void ProcessExitObserved(ProcessExitIdentity identity)
    {
        if (Dispatcher.HasShutdownStarted || Dispatcher.HasShutdownFinished) return;
        try
        {
            Dispatcher.BeginInvoke(new Action(() =>
            {
                if (_windowClosed) return;
                string? message = _exitNotices.Confirm(identity);
                if (message is not null) ShowProcessNotice(global::ProcessLens.Core.SysPulseLocalization.Literal("Processo chiuso"), message);
                if (_selectedExitWatch?.Identity == identity)
                { _selectedExitWatch.Dispose(); _selectedExitWatch = null; }
                if (_requestedExitWatch?.Identity == identity)
                { _requestedExitWatch.Dispose(); _requestedExitWatch = null; }
            }));
        }
        catch (InvalidOperationException) { /* Dispatcher closed while the signal was queued. */ }
    }

