        if (row.Process.ServiceNames.Count != 1)
        {
            MessageBox.Show(this,global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Literal("Questo PID ospita più servizi. Apri la scheda Servizi e seleziona esattamente quale arrestare.")),global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Literal("Selezione necessaria")),MessageBoxButton.OK,MessageBoxImage.Information);
            _serviceFilter = global::ProcessLens.Core.SysPulseLocalization.Literal("Tutti");
            SetServicesMode(true);
            SearchBox.Text = row.Pid.ToString();
            ApplyServiceFilter();
            return;
        }
        try
        {
            var services = await Task.Run(() => _serviceCatalog.Capture());
            var service = services.SingleOrDefault(x =>
                x.Name.Equals(row.Process.ServiceNames[0], StringComparison.OrdinalIgnoreCase) &&
                x.ProcessId == row.Pid);
            if (service is null)
            {
                MessageBox.Show(this,global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Literal("L'associazione servizio/PID è cambiata. Aggiorna ProcessLens e riprova.")),global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Literal("Identità cambiata")),MessageBoxButton.OK,MessageBoxImage.Warning);
                return;
