            await RequestStopServiceAsync(service);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this,global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Impossibile identificare il servizio: "),ex.Message)),global::ProcessLens.Core.SysPulseLocalization.Render(global::ProcessLens.Core.SysPulseLocalization.Literal("Servizio non disponibile")),MessageBoxButton.OK,MessageBoxImage.Warning);
        }
    }

