    private void ShowDetails(ProcessRow row)
    {
        var p = row.Process;
        var i = row.Insight;

        bool en = SysPulseLocalization.IsEnglish;
        DetailProcessIcon.Source = row.IconSource;
        DetailProcessIcon.ToolTip = row.IconDescription;
        DetailFriendlyNameText.Text = i.FriendlyName;
        DetailProcessIdentityText.Text = global::ProcessLens.Core.SysPulseLocalization.Capture($"{(global::ProcessLens.Core.SysPulseLocalization.Opaque(p.Name))}  •  PID {(p.Pid)}  •  {(row.CategoryLabel)}");
        DetailStartTimeText.Text = ProcessStartFormatter.FormatStart(p.StartTime);
        DetailUptimeText.Text = ProcessStartFormatter.FormatElapsed(p.StartTime);
        DeepInspectionStatusText.Text = p.IsDeepInspected
            ? (p.DirectNetworkIdentityVerified == false || (p.NetworkCapturedUtc.HasValue && !p.NetworkAcquisitionComplete)
                ? (en ? global::ProcessLens.Core.SysPulseLocalization.Literal("Partial inspection · network limits apply") : global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi parziale · limiti nei dettagli di rete"))
                : (en ? global::ProcessLens.Core.SysPulseLocalization.Literal("Deep inspection completed") : global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi approfondita completata")))
            : (_deepInspectionInProgress.Contains(p.Pid)
                ? (en ? global::ProcessLens.Core.SysPulseLocalization.Literal("Deep inspection in progress…") : global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi approfondita in corso…"))
                : (en ? global::ProcessLens.Core.SysPulseLocalization.Literal("Quick snapshot") : global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi rapida")));

        var windowsContext = WindowsComponentContext.Describe(p);
        WindowsComponentContextExpander.Visibility = windowsContext.IsApplicable ? Visibility.Visible : Visibility.Collapsed;
        WindowsComponentContextText.Text = SysPulseLocalization.Translate(ReportLayout.Sections(windowsContext.Report)[0].Body);
        WindowsComponentContextExpander.Header = WindowsHostReference.Find(p.Name) is { } hostReference
            ? (en ? global::ProcessLens.Core.SysPulseLocalization.Capture($"{(SysPulseLocalization.Translate(hostReference.Title))} · Microsoft reference") : global::ProcessLens.Core.SysPulseLocalization.Concat(hostReference.Title,global::ProcessLens.Core.SysPulseLocalization.Literal(" · scheda Microsoft")))
            : (en ? global::ProcessLens.Core.SysPulseLocalization.Literal("Windows component · role and telemetry") : global::ProcessLens.Core.SysPulseLocalization.Literal("Componente Windows · ruolo e dati"));
        DetailOwnerText.Text = i.OwnerApp;
        DetailTypeText.Text = SysPulseLocalization.Translate(i.Role);
        var identification = ProcessDetailPresentation.IdentificationExplanation(p, i);
        DetailIdentityConfidenceText.Text = identification[0].Value;
        DetailOwnershipConfidenceText.Text = identification[1].Value;
        DetailRoleConfidenceText.Text = identification[2].Value;

        var origin = ProcessOriginAnalyzer.Analyze(p);
        DetailOriginSummaryText.Text = SysPulseLocalization.Translate(origin.ParentSummary);
        DetailOriginOperationText.Text = SysPulseLocalization.Translate(origin.Operation);
        DetailOriginChainText.Text = origin.Chain;
        DetailOriginCaveatText.Text = SysPulseLocalization.Translate(origin.Limitations);

        DetailWhatIsItText.Text = SysPulseLocalization.Translate(i.Summary);
        DetailActivityText.Text = SysPulseLocalization.Translate(i.WhatIsIt);
        DetailRoleText.Text = string.Empty;
        DetailDetectionBasisText.Text = en
            ? (i.RoleConfidencePercent >= 60
                ? global::ProcessLens.Core.SysPulseLocalization.Literal("SysPulse identified a probable process function. Expand details to see what evidence was used.")
                : global::ProcessLens.Core.SysPulseLocalization.Literal("Available information is insufficient to identify the function of this process."))
            : (i.RoleConfidencePercent >= 60
                ? global::ProcessLens.Core.SysPulseLocalization.Literal("ProcessLens ha identificato una possibile funzione del processo. Apri i dettagli per sapere quali dati ha utilizzato.")
                : global::ProcessLens.Core.SysPulseLocalization.Literal("Le informazioni disponibili non bastano a identificare la funzione di questo processo."));
        _currentDetailRow = row;
        TrackSelectedProcessExit(row);
        RefreshClassificationFacts();
        // Il rapporto grezzo rimane disponibile su richiesta, senza confondere i
        // codici delle regole con le evidenze visibili nella spiegazione principale.

        _currentClassificationAuditInsight = i;
        if (DetailIdentificationExpander.IsExpanded && DetailClassificationAuditExpander.IsExpanded)
            RefreshClassificationAuditGroups();
        DetailWhyRunningText.Text = SysPulseLocalization.Translate(i.WhyRunning);
        DetailCloseImpactText.Text = SysPulseLocalization.Translate(i.CloseImpact);
        DetailRiskText.Text = ProcessDetailPresentation.ClosingRiskLabel(i.CloseRisk);
        ApplyRiskBadge(i.CloseRisk);
        DetailEnglishAnalysisText.Text = string.Empty;

        RefreshCpuDetails(row);
        RefreshMemoryDetails(row);
        DetailProjectShortText.Text = i.ProjectRoot is null
            ? (en ? global::ProcessLens.Core.SysPulseLocalization.Literal("Not identified") : global::ProcessLens.Core.SysPulseLocalization.Literal("Non identificato"))
            : ShortenPath(i.ProjectRoot, 34);
        DetailNetworkStateText.Text = ProcessNetworkPresentation.DescribeEndpointOwners(p);
        RefreshProcessPortsButton.IsEnabled = p.IsDeepInspected && !_networkPortsRefreshing;

        DetailWindowStateText.Text = p.IsDeepInspected
            ? (p.HasVisibleWindow
                ? (en
                    ? global::ProcessLens.Core.SysPulseLocalization.Capture($"Interface: has at least one visible window{(global::ProcessLens.Core.SysPulseLocalization.Opaque((p.WindowTitles.Count > 0 ? global::ProcessLens.Core.SysPulseLocalization.Capture($" — {(global::ProcessLens.Core.SysPulseLocalization.Opaque(p.WindowTitles[0]))}") : string.Empty)))}")
                    : global::ProcessLens.Core.SysPulseLocalization.Capture($"Interfaccia: possiede almeno una finestra visibile{(global::ProcessLens.Core.SysPulseLocalization.Opaque((p.WindowTitles.Count > 0 ? global::ProcessLens.Core.SysPulseLocalization.Capture($" — {(global::ProcessLens.Core.SysPulseLocalization.Opaque(p.WindowTitles[0]))}") : string.Empty)))}"))
                : (en
                    ? global::ProcessLens.Core.SysPulseLocalization.Literal("Interface: no visible top-level window detected in current snapshot.")
                    : global::ProcessLens.Core.SysPulseLocalization.Literal("Interfaccia: nessuna finestra top-level visibile rilevata nelle letture disponibili.")))
            : (en
                ? global::ProcessLens.Core.SysPulseLocalization.Literal("Interface: will be checked during deep inspection.")
                : global::ProcessLens.Core.SysPulseLocalization.Literal("Interfaccia: verrà controllata nell'analisi approfondita."));

        if (DetailTechnicalSectionsExpander.IsExpanded)
            UpdateTechnicalDetails(row);
    }

    private async void RefreshProcessPorts_Click(object sender, RoutedEventArgs e)
    {
        if (_networkPortsRefreshing || _currentDetailRow is not { } row || !row.Process.IsDeepInspected) return;
        _networkPortsRefreshing = true; RefreshProcessPortsButton.IsEnabled = false;
        try
        {
            var refreshed = await Task.Run(() => _deepInspector.RefreshNetwork(row.Process));
            if (_windowClosed || _selectedPid != row.Pid) return;
            int index = _allRows.FindIndex(x => ProcessGrouping.IdentityMatches(row.Process, x.Process));
            if (index < 0) return;
            var merged = MergeDynamicSnapshot(_allRows[index].Process, refreshed);
            var insight = _analyzer.Analyze(merged);
            _allRows[index] = new ProcessRow(merged, insight);
            _deepCache[row.Pid] = (merged.StartTime, merged, insight);
            ApplyFilter(_selectedPid, preserveScroll: true);
        }
        catch (Exception ex)
        {
            if (_selectedPid == row.Pid)
                DetailNetworkStateText.Text = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Aggiornamento porte non riuscito: "),ex.Message);
            AppDiagnostics.Record(global::ProcessLens.Core.SysPulseLocalization.Literal("Aggiornamento porte selezionate non riuscito"), ex);
        }
        finally
        {
            _networkPortsRefreshing = false;
            RefreshProcessPortsButton.IsEnabled = _currentDetailRow?.Process.IsDeepInspected == true;
        }
    }

