    private void RefreshClassificationFacts()
    {
        if (!DetailIdentificationExpander.IsExpanded || _currentDetailRow is not { } row) return;
        if (_renderedClassificationFactsPid == row.Pid &&
            ReferenceEquals(_renderedClassificationFactsInsight, row.Insight)) return;
        DetailClassificationFactsPanel.Children.Clear();
        foreach (var fact in ProcessDetailPresentation.ClassificationFacts(row.Process, row.Insight))
            AddTechnicalFact(DetailClassificationFactsPanel, fact.Label, fact.Value);
        _renderedClassificationFactsInsight = row.Insight;
        _renderedClassificationFactsPid = row.Pid;
    }

