    private void RefreshClassificationAuditGroups()
    {
        if (!DetailIdentificationExpander.IsExpanded || !DetailClassificationAuditExpander.IsExpanded ||
            _currentClassificationAuditInsight is not { } insight ||
            ReferenceEquals(insight, _renderedClassificationAuditInsight))
            return;

        DetailEvidenceTechnicalText.Text = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(insight.DetectionBasis,global::ProcessLens.Core.SysPulseLocalization.Literal("\n")),global::ProcessLens.Core.SysPulseLocalization.Capture($"Punteggio euristico interno: {(insight.RoleConfidencePercent)}/100 (non è una probabilità)\n")),global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal("\n"),insight.Evidence));
        DetailClassificationAuditPanel.Children.Clear();
        var facts = ProcessDetailPresentation.ClassificationAuditFacts(insight);
        foreach (var group in new[]
        {
            global::ProcessLens.Core.SysPulseLocalization.Literal("Valutazione interna"), global::ProcessLens.Core.SysPulseLocalization.Literal("Identità e applicazione"), global::ProcessLens.Core.SysPulseLocalization.Literal("Funzione e ambiente di esecuzione"),
            global::ProcessLens.Core.SysPulseLocalization.Literal("Avvio e relazioni"), global::ProcessLens.Core.SysPulseLocalization.Literal("Altre osservazioni")
        })
        {
            var groupFacts = facts.Where(f => f.Group == group).ToList();
            if (groupFacts.Count == 0) continue;

            var section = ReportView.Section(group, () =>
            {
                var content = new StackPanel { Margin = new Thickness(0, 8, 0, 0) };
                foreach (var fact in groupFacts)
                    AddTechnicalFact(content, fact.Label, fact.Value);
                return content;
            }, expanded: group == global::ProcessLens.Core.SysPulseLocalization.Literal("Valutazione interna"));
            DetailClassificationAuditPanel.Children.Add(section);
        }
        _renderedClassificationAuditInsight = insight;
    }

