    private void RefreshTechnicalDetailGroups()
    {
        if (!DetailTechnicalSectionsExpander.IsExpanded) return;

        DetailIdentityFactsPanel.Children.Clear();
        DetailResourceFactsPanel.Children.Clear();
        DetailNetworkFactsPanel.Children.Clear();
        foreach (var fact in ProcessDetailPresentation.ParseTechnicalFacts(DetailTechnicalContextText.Text))
        {
            var destination = fact.Group switch
            {
                "Risorse" => DetailResourceFactsPanel,
                "Relazioni" => DetailNetworkFactsPanel,
                _ => DetailIdentityFactsPanel
            };
            AddTechnicalFact(destination, fact.Label, fact.Value);
        }

        var evidence = DetailEvidenceText.Text;
        bool sameProcess = _renderedEvidenceGroupsPid == _currentDetailRow?.Pid &&
            _renderedEvidenceGroupsStartTime == _currentDetailRow?.Process.StartTime;
        if (sameProcess && string.Equals(evidence, _renderedEvidenceText, StringComparison.Ordinal)) return;
        var expanded = sameProcess
            ? DetailEvidenceGroupsPanel.Children.OfType<Expander>().Where(e => e.IsExpanded)
                .Select(e => e.Tag as string).OfType<string>().ToHashSet(StringComparer.Ordinal)
            : new HashSet<string>(StringComparer.Ordinal);
        DetailEvidenceGroupsPanel.Children.Clear();
        DetailEvidenceOverviewText.Text = string.Empty;
        _renderedEvidenceGroupsPid = _currentDetailRow?.Pid;
        _renderedEvidenceGroupsStartTime = _currentDetailRow?.Process.StartTime;
        _renderedEvidenceText = evidence;
        if (string.IsNullOrWhiteSpace(evidence)) return;

        var groups = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (var line in evidence.Split('\n'))
        {
            var content = line.Trim().TrimStart('•').Trim();
            if (content.Length == 0) continue;
            var group = ReportLayout.EvidenceGroup(content, ProcessDetailPresentation.EvidenceGroup(content));
            if (!groups.TryGetValue(group, out var values))
                groups[group] = values = new List<string>();
            values.Add(content);
        }
        DetailEvidenceOverviewText.Text =
            global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(groups.Values.Sum(v => v.Count))} voci disponibili, organizzate in {(groups.Count)} capitoli. "),global::ProcessLens.Core.SysPulseLocalization.Literal("Classificazione e attività sono separate. ")),global::ProcessLens.Core.SysPulseLocalization.Literal("Testo originale in fondo."));
        int chapter = 0;
        foreach (var groupName in new[]
        {
            global::ProcessLens.Core.SysPulseLocalization.Literal("Identità e applicazione"), global::ProcessLens.Core.SysPulseLocalization.Literal("Funzione e ambiente di esecuzione"), global::ProcessLens.Core.SysPulseLocalization.Literal("Avvio e relazioni"),
            global::ProcessLens.Core.SysPulseLocalization.Literal("Moduli e librerie"), global::ProcessLens.Core.SysPulseLocalization.Literal("Finestre osservate"), global::ProcessLens.Core.SysPulseLocalization.Literal("Esito delle letture"), global::ProcessLens.Core.SysPulseLocalization.Literal("Altre osservazioni")
        })
        {
            if (!groups.TryGetValue(groupName, out var values)) continue;
            string body = global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal("\n\n"),values);
            var section = ReportView.Section(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(++chapter):00} · {(groupName)} ({(values.Count)})"),
                () => ReportView.Body(body), expanded: expanded.Contains(groupName));
            section.Tag = groupName;
            DetailEvidenceGroupsPanel.Children.Add(section);
        }
    }

