    private void QueueDeepInspection(ProcessRow row)
    {
        if (row.Process.IsDeepInspected)
            return;
        if (!row.Process.StartTime.HasValue)
        {
            if (_selectedPid == row.Pid) DeepInspectionStatusText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi parziale: ora di avvio non disponibile, identità dell'istanza non verificabile.");
            return;
        }

        if (_deepCache.TryGetValue(row.Pid, out var cached) && SameProcessLifetime(row.Process, cached.StartTime))
            return;

        if (!_deepInspectionInProgress.Add(row.Pid))
            return;

        if (_selectedPid == row.Pid)
            DeepInspectionStatusText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi approfondita Windows in corso…");

        _ = DeepInspectAsync(row);
    }

    private async Task DeepInspectAsync(ProcessRow row)
    {
        await _deepInspectionGate.WaitAsync();
        try
        {
            // If the user clicked elsewhere while this request was queued, do not
            // spend resources deeply inspecting a process they are no longer viewing.
            if (_selectedPid != row.Pid)
                return;

            var enriched = await Task.Run(() => _deepInspector.Inspect(row.Process));
            var insight = await Task.Run(() => _analyzer.Analyze(enriched));

            var currentInstance = _allRows.FirstOrDefault(x => x.Pid == row.Pid);
            if (currentInstance is null || !ProcessGrouping.IdentityMatches(row.Process, currentInstance.Process)) return;
            _deepCache[row.Pid] = (row.Process.StartTime, enriched, insight);

            int index = _allRows.FindIndex(x => x.Pid == row.Pid);
            if (index >= 0)
            {
                var current = _allRows[index].Process;
                var merged = MergeDynamicSnapshot(current, enriched);
                _allRows[index] = new ProcessRow(merged, insight);
            }

            if (_selectedPid == row.Pid && !_servicesMode && !_guardianMode && !_memoryMode && !_networkMode && !_systemMode)
                ApplyFilter(_selectedPid, preserveScroll: true);
        }
        catch (Exception ex)
        {
            if (_selectedPid == row.Pid)
                DeepInspectionStatusText.Text = global::ProcessLens.Core.SysPulseLocalization.Capture($"Analisi approfondita non disponibile: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(ex.GetType().Name))}");
        }
        finally
        {
            _deepInspectionInProgress.Remove(row.Pid);
            _deepInspectionGate.Release();
        }
    }

    private void TrackMemoryHistory(IReadOnlyList<ProcessSnapshot> snapshots)
    {
        foreach (var p in snapshots)
        {
            DateTime now = p.MemorySampledUtc ?? DateTime.UtcNow;
            // Do not merge histories for a recycled PID when StartTime is unknown.
            if (!p.StartTime.HasValue) { _memoryHistory.Remove(p.Pid); continue; }
            bool privateResident = p.PrivateWorkingSetAvailable;
            if (!privateResident && !p.WorkingSetAvailable) continue;
            long bytes = privateResident ? p.PrivateWorkingSetBytes : p.WorkingSetBytes;
            if (!_memoryHistory.TryGetValue(p.Pid, out var state) ||
                state.StartTime != p.StartTime.Value || state.PrivateResident != privateResident)
            {
                state = (p.StartTime.Value, privateResident, new MemoryObservationBuffer());
                _memoryHistory[p.Pid] = state;
            }
            state.Samples.Add(now, bytes);
        }
    }

    private MemoryTrendReport? GetMemoryTrend(ProcessSnapshot p)
    {
        if (!p.StartTime.HasValue || !_memoryHistory.TryGetValue(p.Pid, out var state) ||
            state.StartTime != p.StartTime.Value ||
            state.PrivateResident != p.PrivateWorkingSetAvailable)
            return null;
        return MemoryTrendAnalyzer.Analyze(state.PrivateResident ? global::ProcessLens.Core.SysPulseLocalization.Literal("Working Set privato") : global::ProcessLens.Core.SysPulseLocalization.Literal("Working Set totale"),
            state.Samples.ToArray());
    }

    private void TrackCpuHistory(IReadOnlyList<ProcessSnapshot> snapshots)
    {
        DateTime now = DateTime.UtcNow;
        foreach (var p in snapshots)
        {
            if (!p.CpuSampleAvailable || !p.StartTime.HasValue)
            {
                _cpuHistory.Remove(p.Pid);
                _cpuHistoryStarts.Remove(p.Pid);
                continue;
            }
            if (!_cpuHistoryStarts.TryGetValue(p.Pid, out var start) || start != p.StartTime)
            {
                _cpuHistory.Remove(p.Pid);
                _cpuHistoryStarts[p.Pid] = p.StartTime;
            }
            if (!_cpuHistory.TryGetValue(p.Pid, out var queue))
            {
                queue = new Queue<(DateTime TimestampUtc, double Cpu)>();
                _cpuHistory[p.Pid] = queue;
            }

            queue.Enqueue((now, p.CpuPercent));
            while (queue.Count > 40 || (queue.Count > 0 && (now - queue.Peek().TimestampUtc) > TimeSpan.FromSeconds(90)))
                queue.Dequeue();
        }
    }


