    private string DescribeRelatedProcessCpu(ProcessSnapshot selected)
    {
        // Group only by an actual parent/descendant chain, never by exe name alone.
        var rootAncestor = selected.AncestorDetails.LastOrDefault(a =>
            a.VerifiedByStartTime &&
            a.Name.Equals(selected.Name, StringComparison.OrdinalIgnoreCase) &&
            (string.IsNullOrWhiteSpace(selected.ExecutablePath) ||
             string.IsNullOrWhiteSpace(a.ExecutablePath) ||
             selected.ExecutablePath.Equals(a.ExecutablePath, StringComparison.OrdinalIgnoreCase)));
        int rootPid = rootAncestor?.Pid ?? selected.Pid;
        var related = _allRows.Where(x => x.Pid == rootPid ||
                x.Process.AncestorDetails.Any(a => a.Pid == rootPid && a.VerifiedByStartTime))
            .ToArray();
        if (related.Length <= 1)
            return SysPulseLocalization.IsEnglish
                ? global::ProcessLens.Core.SysPulseLocalization.Literal("No other descendants observed in this process branch.")
                : global::ProcessLens.Core.SysPulseLocalization.Literal("Nessun altro discendente osservato per questo ramo.");
        double aggregate = related.Where(x => x.Process.CpuSampleAvailable).Sum(x => x.CpuPercent);
        int coverage = related.Count(x => x.Process.CpuSampleAvailable);
        return SysPulseLocalization.IsEnglish
            ? global::ProcessLens.Core.SysPulseLocalization.Capture($"Origin tree: {(related.Length)} processes, total CPU {(aggregate):F1} % of PC ({(coverage)}/{(related.Length)} sampled; approximate sum).")
            : global::ProcessLens.Core.SysPulseLocalization.Capture($"Albero di origine: {(related.Length)} processi, CPU totale {(aggregate):F1} % del PC ({(coverage)}/{(related.Length)} campionati; somma approssimata).");
    }

    private void CpuGraphCanvas_SizeChanged(object sender, SizeChangedEventArgs e)
    {
