    }

    private void UpdateCpuGraph(int pid)
    {
        CpuGraphLine.Points.Clear();
        if (!_cpuHistory.TryGetValue(pid, out var queue) || queue.Count == 0)
        {
            CpuGraphScaleText.Text = SysPulseLocalization.IsEnglish
                ? global::ProcessLens.Core.SysPulseLocalization.Literal("Graph: waiting for samples")
                : global::ProcessLens.Core.SysPulseLocalization.Literal("Grafico: in attesa di campioni");
            return;
        }
        var samples = queue.Where(x => DateTime.UtcNow - x.TimestampUtc <= TimeSpan.FromSeconds(30))
                           .Select(x => x.Cpu).ToArray();
        if (samples.Length == 0) return;
        double max = Math.Min(100, Math.Max(5, Math.Ceiling(samples.Max() * 1.2)));
        double width = Math.Max(1, CpuGraphCanvas.ActualWidth);
        double height = Math.Max(1, CpuGraphCanvas.ActualHeight);
        for (int j = 0; j < samples.Length; j++)
        {
            double x = samples.Length == 1 ? width : width * j / (samples.Length - 1);
            double y = height * (1 - Math.Min(samples[j], max) / max);
            CpuGraphLine.Points.Add(new Point(x, y));
        }
        CpuGraphScaleText.Text = SysPulseLocalization.IsEnglish
            ? global::ProcessLens.Core.SysPulseLocalization.Capture($"PID CPU trend · vertical scale 0–{(max):F0} % · {(samples.Length)} samples")
            : global::ProcessLens.Core.SysPulseLocalization.Capture($"Andamento CPU del PID · scala verticale 0–{(max):F0} % · {(samples.Length)} campioni");
    }

    private IReadOnlyList<double> RecentCpuSamples(int pid)
    {
        if (!_cpuHistory.TryGetValue(pid, out var queue))
            return Array.Empty<double>();

        DateTime cutoff = DateTime.UtcNow - TimeSpan.FromSeconds(60);
        return queue.Where(x => x.TimestampUtc >= cutoff).Select(x => x.Cpu).ToArray();
    }

