    private static bool IsMemoryQuestion(string question) =>
        System.Text.RegularExpressions.Regex.IsMatch(question, global::ProcessLens.Core.SysPulseLocalization.Literal(@"\bram\b|\b\d+\s*(?:mb|gb)\b"), System.Text.RegularExpressions.RegexOptions.IgnoreCase) ||
        new[] { global::ProcessLens.Core.SysPulseLocalization.Literal("memoria"), global::ProcessLens.Core.SysPulseLocalization.Literal("memory"), global::ProcessLens.Core.SysPulseLocalization.Literal("working set"), global::ProcessLens.Core.SysPulseLocalization.Literal("commit"), global::ProcessLens.Core.SysPulseLocalization.Literal("cache"), global::ProcessLens.Core.SysPulseLocalization.Literal("megabyte"), global::ProcessLens.Core.SysPulseLocalization.Literal("gigabyte") }
            .Any(x => question.Contains(x, StringComparison.OrdinalIgnoreCase));

    private async Task AskSelectedProcessAsync(string question)
    {
        if (_queryBusy)
            return;

        if (_selectedPid is null)
        {
            ShowQueryMessage(global::ProcessLens.Core.SysPulseLocalization.Literal("Process Query"), global::ProcessLens.Core.SysPulseLocalization.Literal("Seleziona prima un processo."), "");
            return;
        }

        question = global::ProcessLens.Core.SysPulseLocalization.Map(question,__s=>__s.Trim());
        if (question.Length == 0)
        {
            ShowQueryMessage(global::ProcessLens.Core.SysPulseLocalization.Literal("Process Query"), global::ProcessLens.Core.SysPulseLocalization.Literal("Scrivi una domanda sul processo selezionato."), "");
            return;
        }

        ProcessRow? row = _allRows.FirstOrDefault(x => x.Pid == _selectedPid.Value);
        if (row is null)
        {
            ShowQueryMessage(global::ProcessLens.Core.SysPulseLocalization.Literal("Process Query"), global::ProcessLens.Core.SysPulseLocalization.Literal("Il processo non è più in esecuzione."), "");
            return;
        }

        _queryBusy = true;
        _copyAnswerBody = string.Empty;
        CopyQueryReportButton.IsEnabled = false;
        AskProcessButton.IsEnabled = false;
        QuickQuestionMenu.IsEnabled = false;
        ProcessQueryAnswerCard.Visibility = Visibility.Visible;
        ProcessQuerySectionsPanel.Children.Clear();
        ProcessQueryOverviewLabel.Visibility = Visibility.Collapsed;
        ProcessQueryOverviewSourceText.Text = string.Empty;
        ProcessQuerySectionsPanel.Visibility = Visibility.Collapsed;
        ProcessQueryAnswerTitleText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi della domanda…");
        ProcessQueryAnswerText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Lettura del processo in corso…");
        ProcessQueryConfidenceText.Text = string.Empty;
        ProcessQueryEvidenceText.Text = string.Empty;
        ProcessQueryAuditPanel.Visibility = Visibility.Collapsed;
        ProcessQueryAuditPanel.Header = global::ProcessLens.Core.SysPulseLocalization.Literal("Registro verifiche RAM — cosa e' stato misurato");
        ProcessQueryAuditText.Text = string.Empty;
        var isMemoryAnalysis = IsMemoryQuestion(question);
        MemoryAnalysisAudit? audit = isMemoryAnalysis ? new MemoryAnalysisAudit(row.Pid) : null;
        void AuditStep(string stage, string result)
        {
            if (audit is null) return;
            audit.Add(stage, result);
            ProcessQueryAuditPanel.Visibility = Visibility.Visible;
            ProcessQueryAuditText.Text = audit.Display;
        }
        AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("IDENTITA'"), global::ProcessLens.Core.SysPulseLocalization.Capture($"PID={(row.Pid)}; verifica istanza in corso"));

        try
        {
            row = await EnsureDeepInspectionForQueryAsync(row);
