            ProcessProgressSample? previous = null;
            if (_progressSamples.TryGetValue(row.Pid, out var stored) && SameProcessLifetime(row.Process, stored.StartTime))
                previous = stored;

            var recentCpu = RecentCpuSamples(row.Pid);
            // The virtual address map is relatively expensive: only for an explicit RAM question.
            MemoryMapSnapshot? memoryMap = null;
            WindowsAllocationReport? allocationReport = null;
            SystemMemoryEvidence? systemMemory = null;
            if (isMemoryAnalysis)
            {
                var fresh = await Task.Run(() => WindowsSelectedMemoryReader.Refresh(row.Process));
                AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("CONTATORI RAM"), fresh.Note.Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("RAM privata="), global::ProcessLens.Core.SysPulseLocalization.Literal("WS privato="), StringComparison.Ordinal));
