                    ShowQueryMessage(global::ProcessLens.Core.SysPulseLocalization.Literal("RAM: misurazione non verificabile"),
                        global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("La lettura e' stata annullata per non attribuire dati a un PID sbagliato. "),fresh.Note),
                        global::ProcessLens.Core.SysPulseLocalization.Literal("NESSUNA VALUTAZIONE"));
                    return;
