                if (row.Process.WorkingSetAvailable)
                    AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("PSAPI"), global::ProcessLens.Core.SysPulseLocalization.Capture($"Working Set totale: {(row.Process.WorkingSetMb):F1} MiB; include pagine condivisibili"));
                if (row.Process.PrivateCommitAvailable)
                    AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("PSAPI"), global::ProcessLens.Core.SysPulseLocalization.Capture($"Commit privato: {(row.Process.PrivateMb):F1} MiB; non RAM fisica"));
                var elapsed = System.Diagnostics.Stopwatch.StartNew();
                memoryMap = await Task.Run(() => _memoryInspector.Capture(row.Pid, row.Process.StartTime));
                elapsed.Stop();
                AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("VirtualQueryEx"), memoryMap.Available
                    ? global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(memoryMap.Regions)} regioni enumerate in {(elapsed.ElapsedMilliseconds)} ms; "),(memoryMap.Truncated ? global::ProcessLens.Core.SysPulseLocalization.Literal("risultato parziale") : global::ProcessLens.Core.SysPulseLocalization.Literal("scansione conclusa"))),global::ProcessLens.Core.SysPulseLocalization.Literal(". ")),global::ProcessLens.Core.SysPulseLocalization.Literal("Oggetti e heap non identificati"))
                    : global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Non disponibile: "),memoryMap.Note));
                // New Windows API probes only on explicit memory analysis of one verified PID.
                var allocationWatch = System.Diagnostics.Stopwatch.StartNew();
                allocationReport = await Task.Run(() => _allocationInspector.Capture(row.Pid, row.Process.StartTime));
                allocationWatch.Stop();
                AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("API ALLOCAZIONI WINDOWS"), allocationReport.Available
                    ? global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"VirtualQueryEx: {(allocationReport.EnumeratedRegions)} regioni, "),global::ProcessLens.Core.SysPulseLocalization.Capture($"{(allocationReport.CommittedGroups)} gruppi; ")),global::ProcessLens.Core.SysPulseLocalization.Capture($"QueryWorkingSetEx: {((allocationReport.SamplesAvailable ? allocationReport.SampledPages.ToString() : global::ProcessLens.Core.SysPulseLocalization.Literal("N/D")))} pagine campionate; ")),global::ProcessLens.Core.SysPulseLocalization.Capture($"durata {(allocationWatch.ElapsedMilliseconds)} ms; ")),(allocationReport.Truncated ? global::ProcessLens.Core.SysPulseLocalization.Literal("risultato parziale.") : global::ProcessLens.Core.SysPulseLocalization.Literal("lettura terminata.")))
                    : global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Non disponibile: "),allocationReport.Note));
                try
                {
                    var physical = WindowsPhysicalMemoryReader.Read();
                    systemMemory = new SystemMemoryEvidence(physical.TotalBytes, physical.AvailableBytes);
                    AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("GlobalMemoryStatusEx"), global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Sistema: {(systemMemory.UsedPercent):F1}% RAM utilizzata, "),global::ProcessLens.Core.SysPulseLocalization.Capture($"{(systemMemory.AvailableMb / 1024d):F2} GiB disponibili.")));
                }
                catch (Exception ex)
                {
                    AppDiagnostics.Record(global::ProcessLens.Core.SysPulseLocalization.Literal("RAM di sistema non disponibile per la valutazione"), ex);
                    AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("GlobalMemoryStatusEx"), global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Dati non disponibili ("),global::ProcessLens.Core.SysPulseLocalization.Opaque(ex.GetType().Name)),global::ProcessLens.Core.SysPulseLocalization.Literal(").")));
                }
            }
            var memoryTrend = GetMemoryTrend(row.Process);
            if (isMemoryAnalysis)
                AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("STORICO"), memoryTrend?.HasTrend == true
                    ? global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(memoryTrend.Samples)} campioni · {(memoryTrend.Seconds):F0} s -> "),global::ProcessLens.Core.SysPulseLocalization.Capture($"delta {(memoryTrend.DeltaMb):+0.0;-0.0;0.0} MiB"))
                    : global::ProcessLens.Core.SysPulseLocalization.Literal("Tendenza: campioni insufficienti"));
            if (_selectedPid != row.Pid)
                return; // Selection changed while the on-demand inspection was running.
            var result = await Task.Run(() => _queryEngine.Ask(
                row.Process,
                row.Insight,
                question,
                previous,
                recentCpu,
                memoryTrend,
                memoryMap,
                systemMemory));

            if (isMemoryAnalysis)
            {
                string familySection = BuildRelatedMemoryEvidence(row, systemMemory);
                string allocSection = allocationReport is not null ? global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("\n\n"),allocationReport.ToEvidenceText()) : "";
                result = result with { Answer = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Map(result.Answer,__s=>__s.TrimEnd()),global::ProcessLens.Core.SysPulseLocalization.Literal("\n\n")),familySection),allocSection) };
            }

            if (result.ProgressSample is not null)
                _progressSamples[row.Pid] = result.ProgressSample;

            ShowQueryResult(result);
            AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("ESITO"), isMemoryAnalysis
                ? global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Rapporto pronto; "),global::ProcessLens.Core.SysPulseLocalization.Literal("dati mancanti nel registro. ")),global::ProcessLens.Core.SysPulseLocalization.Literal("Oggetti interni: serve un profiler."))
                : global::ProcessLens.Core.SysPulseLocalization.Literal("Risposta generata."));
        }
        catch (Exception ex)
        {
            AuditStep(global::ProcessLens.Core.SysPulseLocalization.Literal("ERRORE"), global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi incompleta: "),global::ProcessLens.Core.SysPulseLocalization.Opaque(ex.GetType().Name)),global::ProcessLens.Core.SysPulseLocalization.Literal(".")));
            ShowQueryMessage(global::ProcessLens.Core.SysPulseLocalization.Literal("Process Query"), global::ProcessLens.Core.SysPulseLocalization.Capture($"Non riesco a completare questa interrogazione: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(ex.GetType().Name))}."), global::ProcessLens.Core.SysPulseLocalization.Literal("ERRORE"));
        }
        finally
        {
            _queryBusy = false;
            CopyQueryReportButton.IsEnabled = _copyAnswerBody.Length > 0;
            AskProcessButton.IsEnabled = true;
            QuickQuestionMenu.IsEnabled = true;
        }
