    private async Task<ProcessRow> EnsureDeepInspectionForQueryAsync(ProcessRow row)
    {
        // Query-time inspection is intentionally fresh. The normal detail panel may reuse
        // a deep-cache for the PID lifetime, but progress/window/network evidence can change.
        // A user query is infrequent, so refreshing only this one PID keeps the global loop light.
        await _deepInspectionGate.WaitAsync();
        try
        {
            ProcessRow? latestRow = _allRows.FirstOrDefault(x => x.Pid == row.Pid);
            if (latestRow is not null)
                row = latestRow;

            var enriched = await Task.Run(() => _deepInspector.Inspect(row.Process));
            var insight = await Task.Run(() => _analyzer.Analyze(enriched));
            var currentInstance = _allRows.FirstOrDefault(x => x.Pid == row.Pid);
            if (currentInstance is null || !ProcessGrouping.IdentityMatches(row.Process, currentInstance.Process))
                throw new InvalidOperationException(global::ProcessLens.Core.SysPulseLocalization.Literal("Istanza del processo cambiata durante l’analisi; seleziona di nuovo il PID."));
            _deepCache[row.Pid] = (row.Process.StartTime, enriched, insight);

            int index = _allRows.FindIndex(x => x.Pid == row.Pid);
            if (index >= 0)
            {
                var merged = MergeDynamicSnapshot(_allRows[index].Process, enriched);
                var updated = new ProcessRow(merged, insight);
                _allRows[index] = updated;
                if (!_servicesMode && !_guardianMode && !_memoryMode && !_networkMode && !_systemMode)
                    ApplyFilter(_selectedPid, preserveScroll: true);
                return updated;
            }

            return new ProcessRow(enriched, insight);
        }
        finally
        {
            _deepInspectionGate.Release();
        }
    }

