        ProcessQueryConfidenceText.Text = string.IsNullOrWhiteSpace(result.Confidence)
            ? string.Empty
            : (en ? global::ProcessLens.Core.SysPulseLocalization.Capture($"Data & limits: {(result.Confidence)}") : global::ProcessLens.Core.SysPulseLocalization.Capture($"Dati e limiti: {(result.Confidence)}"));
        ProcessQueryEvidenceText.Text = result.Evidence.Count == 0
            ? string.Empty
            : global::ProcessLens.Core.SysPulseLocalization.Concat((en ? global::ProcessLens.Core.SysPulseLocalization.Literal("Sources: ") : global::ProcessLens.Core.SysPulseLocalization.Literal("Fonti: ")),global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(" · "),result.Evidence.Take(5)));
    }

