    private void ProcessQueryAuditText_TextChanged(object sender, TextChangedEventArgs e)
    {
        if (ProcessQueryAuditEntriesPanel is null || ProcessQueryAuditOverviewText is null ||
            ProcessQueryAuditLocationText is null || ProcessQueryAuditPanel is null) return;
        if (CopyQueryAuditButton is not null) CopyQueryAuditButton.IsEnabled = ProcessQueryAuditText.Text.Length > 0;
        _auditDocument = AuditLogPresentation.Parse(ProcessQueryAuditText.Text);
        ProcessQueryAuditOverviewText.Text = AuditLogPresentation.Overview(_auditDocument);
        ProcessQueryAuditLocationText.Text = _auditDocument.Location;
        _auditLogView ??= new AuditLogView(ProcessQueryAuditEntriesPanel);
        if (ProcessQueryAuditPanel.IsExpanded && ProcessQueryAuditPanel.Visibility == Visibility.Visible)
            _auditLogView.Render(_auditDocument);
        else _auditLogView.Clear();
    }

    private void ProcessQueryAuditPanel_Expanded(object sender, RoutedEventArgs e)
    {
        if (!ReferenceEquals(sender, e.OriginalSource) || ProcessQueryAuditEntriesPanel is null) return;
        _auditLogView ??= new AuditLogView(ProcessQueryAuditEntriesPanel);
        _auditLogView.Render(_auditDocument);
    }

