    private void RenderQueryAnswer(ProcessQueryResult result)
    {
        ProcessQuerySectionsPanel.Children.Clear();
        ProcessQueryOverviewLabel.Visibility = Visibility.Collapsed;
        ProcessQueryOverviewSourceText.Text = string.Empty;
        ProcessQuerySectionsPanel.Visibility = Visibility.Collapsed;
        if (!result.Answer.Replace(global::ProcessLens.Core.SysPulseLocalization.Literal("\r\n"), global::ProcessLens.Core.SysPulseLocalization.Literal("\n"), StringComparison.Ordinal).Split('\n')
            .Any(line => line.StartsWith(global::ProcessLens.Core.SysPulseLocalization.Literal("■ "), StringComparison.Ordinal)))
        {
            ProcessQueryAnswerText.Text = result.Answer;
            return;
        }

        // Parse only explicit headings: blank/unheaded paragraphs remain in their section.
        // The complete original result.Answer is copied separately, without reconstruction.
        var sections = ReportLayout.Sections(result.Answer);
        ProcessQueryOverviewLabel.Visibility = Visibility.Visible;
        ProcessQueryOverviewSourceText.Text = sections[0].Heading;
        ProcessQueryAnswerText.Text = sections[0].Body;
        for (int index = 1; index < sections.Count; index++)
        {
            var section = sections[index];
            ProcessQuerySectionsPanel.Children.Add(ReportView.Section(
                global::ProcessLens.Core.SysPulseLocalization.Capture($"{(index):00} · {(section.Heading)}"), () => ReportView.Body(section.Body)));
        }
        ProcessQuerySectionsPanel.Visibility = ProcessQuerySectionsPanel.Children.Count > 0
            ? Visibility.Visible : Visibility.Collapsed;
    }

