    private void ApplyRiskBadge(string risk)
    {
        string upper = global::ProcessLens.Core.SysPulseLocalization.Map(risk,__s=>__s.ToUpperInvariant());

        if (upper.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("CRITICO")))
        {
            RiskBadge.Background = new SolidColorBrush(Color.FromRgb(255, 232, 232));
            DetailRiskText.Foreground = new SolidColorBrush(Color.FromRgb(164, 34, 34));
        }
        else if (upper.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("ALTO")))
        {
            RiskBadge.Background = new SolidColorBrush(Color.FromRgb(255, 239, 218));
            DetailRiskText.Foreground = new SolidColorBrush(Color.FromRgb(146, 78, 0));
        }
        else if (upper.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("MEDIO")))
        {
            RiskBadge.Background = new SolidColorBrush(Color.FromRgb(255, 247, 214));
            DetailRiskText.Foreground = new SolidColorBrush(Color.FromRgb(126, 90, 0));
        }
        else if (upper.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("BASSO")))
        {
            RiskBadge.Background = new SolidColorBrush(Color.FromRgb(226, 247, 234));
            DetailRiskText.Foreground = new SolidColorBrush(Color.FromRgb(31, 110, 63));
        }
        else
        {
            RiskBadge.Background = new SolidColorBrush(Color.FromRgb(238, 241, 245));
            DetailRiskText.Foreground = new SolidColorBrush(Color.FromRgb(75, 85, 99));
        }
    }

    private static string ShortenPath(string path, int maxLength)
    {
        if (path.Length <= maxLength)
            return path;

        string name = System.IO.Path.GetFileName(path.TrimEnd('\\', '/'));
        if (!string.IsNullOrWhiteSpace(name))
            return global::ProcessLens.Core.SysPulseLocalization.Capture($"…\\{(global::ProcessLens.Core.SysPulseLocalization.Opaque(name))}");

        int keep = Math.Min(maxLength - 1, path.Length);
        return global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("…"),global::ProcessLens.Core.SysPulseLocalization.Opaque(path.Substring(path.Length - keep, keep)));
    }

