            [global::ProcessLens.Core.SysPulseLocalization.Literal("WSL")] = FilterWslButton
        };

        foreach (var pair in buttons)
        {
            bool active = pair.Key == _activeFilter;
            pair.Value.Background = active
                ? new SolidColorBrush(Color.FromRgb(225, 236, 252))
                : Brushes.White;
            pair.Value.BorderBrush = active
                ? new SolidColorBrush(Color.FromRgb(112, 154, 214))
                : new SolidColorBrush(Color.FromRgb(217, 221, 227));
            pair.Value.Foreground = active
                ? new SolidColorBrush(Color.FromRgb(33, 86, 160))
                : new SolidColorBrush(Color.FromRgb(55, 65, 81));
        }
    }

