    private void SetWorkspaceMode(string mode)
    {
        _workspaceNavigation++;
        bool services = mode == global::ProcessLens.Core.SysPulseLocalization.Literal("services");
        if (!services) _serviceHostScope = null;
        bool guardian = mode == global::ProcessLens.Core.SysPulseLocalization.Literal("guardian");
        bool memory = mode == global::ProcessLens.Core.SysPulseLocalization.Literal("memory");
        bool network = mode == global::ProcessLens.Core.SysPulseLocalization.Literal("network");
        bool system = mode == global::ProcessLens.Core.SysPulseLocalization.Literal("system");
        _systemMode = system;
        _networkMode = network;
        _memoryMode = memory;
        _guardianMode = guardian;
        _servicesMode = services;
        // Keep the services-mode gate independent from any high-load process interval.
        _timer.Interval = MonitorRefreshPolicy.NormalProcessInterval;
        if (guardian && GuardianDashboard is null)
        {
            GuardianDashboard = new GuardianDashboardView();
            UiTreeLocalizer.Apply(GuardianDashboard, SysPulseLocalization.CurrentLanguage);
            GuardianDashboardHost.Content = GuardianDashboard;
        }
        if (memory && MemoryDashboard is null)
        {
            MemoryDashboard = new MemoryDashboardView();
            MemoryDashboard.InspectProcessRequested += pid => _ = InspectPidMemoryFromDashboardAsync(pid);
            MemoryDashboard.DetailsRequested += target => _ = OpenMemoryDetailsAsync(target);
            UiTreeLocalizer.Apply(MemoryDashboard, SysPulseLocalization.CurrentLanguage);
            MemoryDashboardHost.Content = MemoryDashboard;
        }
        if (network && NetworkDevices is null)
        {
            NetworkDevices = new NetworkDevicesView();
            UiTreeLocalizer.Apply(NetworkDevices, SysPulseLocalization.CurrentLanguage);
            NetworkDevicesHost.Content = NetworkDevices;
        }
        if (system && SystemProcesses is null)
        {
            SystemProcesses = new SystemProcessesView();
            SystemProcesses.AnalysisRequested += target => _ = OpenSystemProcessAsync(target);
            UiTreeLocalizer.Apply(SystemProcesses, SysPulseLocalization.CurrentLanguage);
            SystemProcessesHost.Content = SystemProcesses;
        }
        SystemProcessesHost.Visibility = system ? Visibility.Visible : Visibility.Collapsed;
        ProcessDetectedCounter.Visibility = system ? Visibility.Collapsed : Visibility.Visible;
        ProcessVisibleCounter.Visibility = system ? Visibility.Collapsed : Visibility.Visible;
        SystemProcesses?.SetActive(system && IsVisible && WindowState != WindowState.Minimized);
        NetworkDevicesHost.Visibility = network ? Visibility.Visible : Visibility.Collapsed;
        NetworkDevices?.SetActive(network && IsVisible && WindowState != WindowState.Minimized);
        GuardianDashboardHost.Visibility = guardian ? Visibility.Visible : Visibility.Collapsed;
        GuardianDashboard?.SetActive(guardian);
        MemoryDashboardHost.Visibility = memory ? Visibility.Visible : Visibility.Collapsed;
        MemoryDashboard?.SetActive(memory);
        ProcessWorkspace.Visibility = (services || guardian || memory || network || system) ? Visibility.Collapsed : Visibility.Visible;
        ServiceWorkspace.Visibility = services ? Visibility.Visible : Visibility.Collapsed;
        ProcessFilters.Visibility = (services || guardian || memory || network || system) ? Visibility.Collapsed : Visibility.Visible;
        ServiceFilters.Visibility = services ? Visibility.Visible : Visibility.Collapsed;
        if (guardian || memory || network || system) SearchBox.Clear();
        SearchBox.IsEnabled = !(guardian || memory || network || system);
        SearchBox.ToolTip = services ? global::ProcessLens.Core.SysPulseLocalization.Literal("Cerca servizi per nome, descrizione, stato, tipo di avvio o PID") :
            global::ProcessLens.Core.SysPulseLocalization.Literal("Cerca processi per nome, PID, tipo suggerito o processo padre");
        NavServicesButton.Background = services ? new SolidColorBrush(Color.FromRgb(225,236,252)) : Brushes.White;
        NavProcessesButton.Background = (!services && !guardian && !memory && !network && !system) ? new SolidColorBrush(Color.FromRgb(225,236,252)) : Brushes.White;
        NavGuardianButton.Background = guardian ? new SolidColorBrush(Color.FromRgb(225,236,252)) : Brushes.White;
        NavMemoryButton.Background = memory ? new SolidColorBrush(Color.FromRgb(225,236,252)) : Brushes.White;
        NavSystemButton.Background = system ? new SolidColorBrush(Color.FromRgb(225,236,252)) : Brushes.White;
        NavNetworkButton.Background = network ? new SolidColorBrush(Color.FromRgb(225,236,252)) : Brushes.White;
        if (services)
        {
            StartServiceEventWatcher();
            ApplyServiceFilter();
            _ = RefreshServicesAsync(_allServices.Count == 0);
        }
        else
        {
            _profilerSession?.Cancel();
            _serviceEventsWatcher?.Dispose();
            _serviceEventsWatcher = null;
            if (!guardian && !memory && !network && !system) ApplyFilter(_selectedPid, preserveScroll: true);
        }
    }

