    private async Task OpenSystemProcessAsync(SystemProcessEntry target)
    {
        if (!_systemMode || !IsVisible || WindowState == WindowState.Minimized) return;
        int navigation = _workspaceNavigation;
        try
        {
            await RefreshAsync();
            if (_windowClosed || navigation != _workspaceNavigation || !_systemMode || !IsVisible || WindowState == WindowState.Minimized) return;
            var current = _allRows.FirstOrDefault(row => row.Pid == target.Pid);
            if (current is null || !SystemProcessPresentation.SameInstance(target, current.Process))
            {
                SystemProcesses?.ShowNavigationProblem(global::ProcessLens.Core.SysPulseLocalization.Literal("Processo terminato, istanza cambiata o avvio N/D. Aggiorna l'elenco; i dettagli non sono stati aperti."));
                return;
            }
            _activeFilter = global::ProcessLens.Core.SysPulseLocalization.Literal("Tutti"); SearchBox.Clear(); SetFilterButtonState();
            _selectedPid = target.Pid;
            SetWorkspaceMode(global::ProcessLens.Core.SysPulseLocalization.Literal("processes")); ApplyFilter(target.Pid);
            if (ProcessList.SelectedItem is not null) ProcessList.ScrollIntoView(ProcessList.SelectedItem);
        }
        catch (Exception ex)
        {
            if (!_windowClosed && navigation == _workspaceNavigation && _systemMode)
                SystemProcesses?.ShowNavigationProblem(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Analisi non disponibile: "),ex.Message));
            AppDiagnostics.Record(global::ProcessLens.Core.SysPulseLocalization.Literal("Apertura analisi da Sistema Windows non riuscita"), ex);
        }
    }

