    private static DateTime? ReadProcessStartUtc(int pid)
    {
        try { using var process = Process.GetProcessById(pid); return process.StartTime.ToUniversalTime(); }
        catch (Exception ex) when (ex is ArgumentException or InvalidOperationException or System.ComponentModel.Win32Exception) { return null; }
    }

    private async Task OpenMemoryDetailsAsync(MemoryDetailsTarget target)
    {
        _serviceHostScope = new();
        _serviceFilter = global::ProcessLens.Core.SysPulseLocalization.Literal("Tutti");
        _selectedServiceName = null;
        SearchBox.Clear();
        SetServicesMode(true);
        int request = _workspaceNavigation;
        ServiceScopeText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Verifica dei processi e delle associazioni SCM in corso…");
        try
        {
            if (!_allRows.Any(r => r.Pid == target.Pid)) await RefreshAsync();
            if (_windowClosed || request != _workspaceNavigation) return;
            var candidates = _allRows.Where(r => target.Grouped
                ? string.Equals(System.IO.Path.GetFileNameWithoutExtension(r.Name), System.IO.Path.GetFileNameWithoutExtension(target.ExecutableName), StringComparison.OrdinalIgnoreCase)
                : r.Pid == target.Pid).Select(r => r.Process).ToArray();
            var result = await Task.Run(() =>
            {
                var before = candidates.Select(p => new ServiceHostCandidate(p.Pid, p.Name, p.StartTime?.ToUniversalTime(), ReadProcessStartUtc(p.Pid)))
                    .Where(p => ServiceNavigation.Matches(target, p)).ToArray();
                var catalog = _serviceCatalog.Capture();
                var hosts = before.Where(p => ReadProcessStartUtc(p.Pid) == p.SnapshotStartUtc)
                    .ToDictionary(p => p.Pid, p => p.SnapshotStartUtc!.Value);
                return (Catalog: catalog, Hosts: hosts);
            });
            if (_windowClosed || request != _workspaceNavigation || !_servicesMode) return;
            _allServices = result.Catalog.ToList();
            _servicesFetchedUtc = DateTime.UtcNow;
            _serviceHostScope = result.Hosts;
            var matches = _allServices.Where(service => ServiceNavigation.Includes(service.ProcessId, _serviceHostScope)).ToArray();
            ServiceScopeText.Text = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"{(matches.Length)} servizi SCM associati a {(result.Hosts.Count)} PID verificati"),(target.Grouped ? global::ProcessLens.Core.SysPulseLocalization.Capture($" del gruppo RAM per nome «{(target.ExecutableName)}».") : global::ProcessLens.Core.SysPulseLocalization.Capture($" (richiesta PID {(target.Pid)}).")));
            if (matches.Length == 1) _selectedServiceName = matches[0].Name;
            ApplyServiceFilter();
            if (matches.Length == 1) OpenServiceDetails(matches[0]);
            else if (matches.Length > 1) ServiceList.Focus();
            else
            {
                // A background category does not prove that a process hosts a Windows service.
                var representative = candidates.FirstOrDefault(p => p.Pid == target.Pid);
                bool stillSame = representative is not null && ServiceNavigation.Matches(target,
                    new(representative.Pid, representative.Name, representative.StartTime?.ToUniversalTime(), ReadProcessStartUtc(target.Pid)));
                if (stillSame)
                {
                    _selectedPid = target.Pid; _activeFilter = global::ProcessLens.Core.SysPulseLocalization.Literal("Tutti");
                    SearchBox.Clear(); SetFilterButtonState(); SetWorkspaceMode(global::ProcessLens.Core.SysPulseLocalization.Literal("processes")); ApplyFilter(target.Pid);
                    ShowProcessNotice(global::ProcessLens.Core.SysPulseLocalization.Literal("Dettagli processo"), global::ProcessLens.Core.SysPulseLocalization.Literal("Nessun servizio SCM associato ai PID verificati. Aperto il processo selezionato o il PID rappresentativo del gruppo RAM."));
                }
                else ServiceScopeText.Text += global::ProcessLens.Core.SysPulseLocalization.Literal(" Processo terminato o identità non verificabile; nessun PID sostitutivo selezionato.");
            }
        }
        catch (Exception ex)
        {
            if (!_windowClosed && request == _workspaceNavigation)
                ServiceScopeText.Text = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Associazioni non verificabili: "),ex.Message);
            AppDiagnostics.Record(global::ProcessLens.Core.SysPulseLocalization.Literal("Navigazione RAM verso servizi non riuscita"), ex);
        }
    }

