    private void OpenServiceDetails(ServiceSnapshot service)
    {
        _serviceDetailsWindow?.Close();
        var details = new ServiceDetailsWindow(service, _servicesFetchedUtc == DateTime.MinValue ? null : _servicesFetchedUtc) { Owner = this };
        _serviceDetailsWindow = details;
        details.Closed += (_, _) => { if (ReferenceEquals(_serviceDetailsWindow, details)) _serviceDetailsWindow = null; };
        details.Show();
    }

    private async Task RefreshServicesAsync(bool force)
    {
        if (_servicesRefreshing || (!force && DateTime.UtcNow - _servicesFetchedUtc < MonitorRefreshPolicy.ServiceCatalogInterval))
            return;
        _servicesRefreshing = true;
        int navigation = _workspaceNavigation;
        try
        {
            var elapsed = Stopwatch.StartNew();
            var services = await Task.Run(() => _serviceCatalog.Capture());
            if (_windowClosed || navigation != _workspaceNavigation) return;
            var scope = _serviceHostScope;
            if (scope is not null)
            {
                var stillLive = await Task.Run(() => scope.Where(pair => ReadProcessStartUtc(pair.Key) == pair.Value).ToDictionary(pair => pair.Key, pair => pair.Value));
                if (ReferenceEquals(scope, _serviceHostScope)) _serviceHostScope = stillLive;
            }
            if (_windowClosed || navigation != _workspaceNavigation) return;
            elapsed.Stop();
            _allServices = services.ToList();
            if (elapsed.Elapsed >= TimeSpan.FromSeconds(1) &&
                DateTime.UtcNow - _lastSlowServiceLoggedUtc > TimeSpan.FromMinutes(2))
            {
                AppDiagnostics.Record(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Capture($"Lettura servizi lenta: {(_allServices.Count)} servizi, "),global::ProcessLens.Core.SysPulseLocalization.Capture($"durata {(elapsed.ElapsedMilliseconds)} ms; intervallo automatico ")),global::ProcessLens.Core.SysPulseLocalization.Capture($"{(MonitorRefreshPolicy.ServiceCatalogInterval.TotalSeconds):F0} s.")));
                _lastSlowServiceLoggedUtc = DateTime.UtcNow;
            }
            _servicesFetchedUtc = DateTime.UtcNow;
            if (_servicesMode) ApplyServiceFilter();
        }
        catch (Exception ex)
        {
            if (_servicesMode)
                ServicesCountText.Text = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Servizi non disponibili: "),ex.Message);
        }
        finally { _servicesRefreshing = false; }
    }

    private void ApplyServiceFilter()
    {
        if (!_servicesMode) return;
        string search = SearchBox.Text.Trim();
        IEnumerable<ServiceSnapshot> items = _allServices.Where(service => ServiceNavigation.Includes(service.ProcessId, _serviceHostScope));
        items = _serviceFilter switch
        {
            "Attivi" => items.Where(x => x.IsRunning),
            "Arrestati" => items.Where(x => x.StateCode == 1),
            _ => items
        };
        if (search.Length > 0)
            items = items.Where(x =>
                Contains(x.DisplayName, search) || Contains(x.Name, search) ||
                Contains(x.Description, search) || Contains(x.StateLabel, search) ||
                Contains(x.StartupLabel, search) || x.ProcessId.ToString().Contains(search, StringComparison.OrdinalIgnoreCase));
        items = _serviceSortMode switch
        {
            "Nome A-Z" or "Display name (A-Z)" or "Name (A-Z)" => items.OrderBy(x => x.DisplayName, StringComparer.CurrentCultureIgnoreCase),
            "Tipo di avvio" or "Startup type" => items.OrderBy(x => x.StartupCode ?? 9).ThenBy(x => x.DisplayName, StringComparer.CurrentCultureIgnoreCase),
            "PID" => items.OrderByDescending(x => x.ProcessId).ThenBy(x => x.DisplayName, StringComparer.CurrentCultureIgnoreCase),
            _ => items.OrderByDescending(x => x.IsRunning).ThenBy(x => x.DisplayName, StringComparer.CurrentCultureIgnoreCase)
        };
        var visible = items.ToList();
        ServicesCountText.Text = SysPulseLocalization.IsEnglish
            ? global::ProcessLens.Core.SysPulseLocalization.Capture($"Installed: {(_allServices.Count)}   Running: {(_allServices.Count(x => x.IsRunning))}   Stopped: {(_allServices.Count(x => x.StateCode == 1))}   Shown: {(visible.Count)}")
            : global::ProcessLens.Core.SysPulseLocalization.Capture($"Installati: {(_allServices.Count)}   Attivi: {(_allServices.Count(x => x.IsRunning))}   Arrestati: {(_allServices.Count(x => x.StateCode == 1))}   Visualizzati: {(visible.Count)}");
        var saved = _selectedServiceName;
        _suppressServiceSelection = true;
        try
        {
            ServiceList.ItemsSource = visible;
            _selectedService = visible.FirstOrDefault(x => string.Equals(x.Name, saved, StringComparison.OrdinalIgnoreCase));
            ServiceList.SelectedItem = _selectedService;
            if (_selectedService is not null) ShowServiceDetails(_selectedService);
            else ClearServiceDetails();
        }
        finally { _suppressServiceSelection = false; }
    }

    // A service row is not the process hosting it. Right-click offers an orderly
    // SCM stop for the named service and an explicit navigation to the host PID.
    // Build the ContextMenu after its ListViewItem is loaded: placing an event-wired
    // ContextMenu in Window.Resources caused a WPF connectionId crash in v0.11.2.
    private void ServiceItem_Loaded(object sender, RoutedEventArgs e)
    {
        if (sender is not ListViewItem item || item.ContextMenu is not null) return;
        var menu = new ContextMenu();
        menu.Opened += ServiceContextMenu_Opened;
        item.ContextMenu = menu;
    }

    private void ServiceItem_RightMouseDown(object sender, MouseButtonEventArgs e)
    {
        if (sender is ListViewItem { DataContext: ServiceSnapshot } item)
        {
            item.IsSelected = true;
            item.Focus();
        }
    }

    private void ServiceContextMenu_Opened(object sender, RoutedEventArgs e)
    {
        if (sender is not ContextMenu menu) return;
        menu.Items.Clear();
        if (menu.PlacementTarget is not ListViewItem { DataContext: ServiceSnapshot service }) return;

        // Each MenuItem keeps the service identity from the right-clicked row.
        // An asynchronous refresh must not redirect an action to another selection.
        var decision = ServiceStopPolicy.Evaluate(service,
            Environment.GetFolderPath(Environment.SpecialFolder.Windows));
        var stop = new global::ProcessLens.App.LocalizedMenuItem        {
            Header = global::ProcessLens.Core.SysPulseLocalization.Literal("Arresta servizio…"),
            Tag = service,
            IsEnabled = !_serviceStopBusy && decision.Allowed,
            ToolTip = _serviceStopBusy ? global::ProcessLens.Core.SysPulseLocalization.Literal("Un arresto di servizio è già in corso.") : decision.Reason
        };
        ToolTipService.SetShowOnDisabled(stop, true);
        stop.Click += ServiceContextStop_Click;
        menu.Items.Add(stop);
        menu.Items.Add(new Separator());

        var host = new global::ProcessLens.App.LocalizedMenuItem        {
            Header = global::ProcessLens.Core.SysPulseLocalization.Literal("Mostra processo ospitante"),
            Tag = service,
            IsEnabled = service.ProcessId > 0 && _allRows.Any(r => r.Pid == service.ProcessId),
            ToolTip = global::ProcessLens.Core.SysPulseLocalization.Literal("Apri il processo che ospita il servizio; non lo termina.")
        };
        host.Click += ServiceContextShowHost_Click;
        menu.Items.Add(host);

        var copyName = new global::ProcessLens.App.LocalizedMenuItem{ Header = global::ProcessLens.Core.SysPulseLocalization.Literal("Copia nome servizio"), Tag = service };
        copyName.Click += ServiceContextCopyName_Click;
        menu.Items.Add(copyName);
    }

