    private void ShowServiceDetails(ServiceSnapshot service)
    {
        ServiceDetailName.Text = service.DisplayName;
        ServiceDetailIdentity.Text = global::ProcessLens.Core.SysPulseLocalization.Capture($"Nome tecnico: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(service.Name))} · {(service.HostType)}");
        ServiceDetailStatus.Text = global::ProcessLens.Core.SysPulseLocalization.Capture($"Stato: {(service.StateLabel)}   |   Avvio: {(service.StartupLabel)}");
        ServiceDetailDescription.Text = string.IsNullOrWhiteSpace(service.Description)
            ? global::ProcessLens.Core.SysPulseLocalization.Literal("Descrizione: N/D. Funzione sconosciuta.")
            : service.Description;
        ServiceDetailWhy.Text = ServiceExplanation.WhyRunning(service);
        int hosted = _allServices.Count(x => x.ProcessId > 0 && x.ProcessId == service.ProcessId);
        string? processName = _allRows.FirstOrDefault(x => x.Pid == service.ProcessId)?.Name;
        ServiceDetailHost.Text = ServiceExplanation.Association(service, hosted, processName);
        ServiceShowProcessButton.IsEnabled = service.ProcessId > 0 && _allRows.Any(x => x.Pid == service.ProcessId);
        var stopDecision = ServiceStopPolicy.Evaluate(service,
            Environment.GetFolderPath(Environment.SpecialFolder.Windows));
        ServiceStopButton.IsEnabled = !_serviceStopBusy && stopDecision.Allowed;
        ServiceStopButton.ToolTip = stopDecision.Reason;
        ServiceDetailDependencies.Text = global::ProcessLens.Core.SysPulseLocalization.Join(Environment.NewLine,new[]
        {
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Tipo di avvio: {(service.StartupLabel)}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Dipende da servizi: {((service.Dependencies.Count == 0 ? global::ProcessLens.Core.SysPulseLocalization.Literal("Nessuno dichiarato") : global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(", "),service.Dependencies)))}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Dipende da gruppi: {((service.GroupDependencies.Count == 0 ? global::ProcessLens.Core.SysPulseLocalization.Literal("Nessuno dichiarato") : global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(", "),service.GroupDependencies)))}"),
            global::ProcessLens.Core.SysPulseLocalization.Literal("Dipendenze configurate; richiedente dell’avvio sconosciuto.")
        });
        ServiceDetailImpact.Text = ServiceExplanation.Impact(service);
        ServiceHistoryRefreshButton.IsEnabled = true;
        _ = LoadServiceHistoryAsync(service, force: false);
        ServiceDetailTechnical.Text = global::ProcessLens.Core.SysPulseLocalization.Join(Environment.NewLine,new[]
        {
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Nome: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(service.Name))}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Display name: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(service.DisplayName))}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Stato SCM: {(service.StateCode)} ({(service.StateLabel)})"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"PID ospitante: {(service.ProcessIdLabel)}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Service type: 0x{(service.ServiceType):X}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Account: {(service.AccountName ?? global::ProcessLens.Core.SysPulseLocalization.Literal("N/D"))}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"ImagePath: {(service.BinaryPath ?? global::ProcessLens.Core.SysPulseLocalization.Literal("N/D"))}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Avvio configurato (SCM): {(service.StartupLabel)}")
        });
    }

    private void StartServiceEventWatcher()
    {
        if (_serviceEventsWatcher is not null) return;
        _serviceEventsWatcher = new WindowsServiceEventHistory.LiveWatcher(eventServiceName =>
        {
            // EventLogWatcher raises on a background thread: only touch WPF from dispatcher.
            if (Dispatcher.HasShutdownStarted || Dispatcher.HasShutdownFinished) return;
            Dispatcher.BeginInvoke(new Action(() =>
            {
                var service = _selectedService;
                if (!_servicesMode || service is null) return;
                bool matches = eventServiceName.Equals(service.Name, StringComparison.OrdinalIgnoreCase) ||
                    eventServiceName.Equals(service.DisplayName, StringComparison.OrdinalIgnoreCase);
                if (matches) _ = LoadServiceHistoryAsync(service, force: true);
            }));
        });
    }

    private async Task LoadServiceHistoryAsync(ServiceSnapshot service, bool force)
    {
        // Only selected service; do not scan the log for every refresh or every service.
        if (!_servicesMode || !string.Equals(_selectedServiceName, service.Name, StringComparison.OrdinalIgnoreCase))
            return;
        if (!force && _serviceEventsCache.TryGetValue(service.Name, out var entry) &&
            DateTime.UtcNow - entry.CachedUtc < TimeSpan.FromMinutes(2))
        {
            RenderServiceHistory(service, entry.Result);
            return;
        }
        if (string.Equals(_serviceEventsLoading, service.Name, StringComparison.OrdinalIgnoreCase)) return;
        _serviceEventsLoading = service.Name;
        int request = ++_serviceEventsRequest;
        ServiceHistoryStatusText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Consultazione della cronologia SCM in corso...");
        await _serviceEventsGate.WaitAsync();
        try
        {
            if (request != _serviceEventsRequest) return;
            var result = await Task.Run(() => _serviceEvents.Read(service));
            _serviceEventsCache[service.Name] = (DateTime.UtcNow, result);
            if (request == _serviceEventsRequest && _servicesMode &&
                string.Equals(_selectedServiceName, service.Name, StringComparison.OrdinalIgnoreCase))
                RenderServiceHistory(service, result);
        }
        catch (Exception ex)
        {
            if (request == _serviceEventsRequest)
            {
                ServiceHistoryStatusText.Text = global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Errore nella lettura del registro: "),ex.Message);
                ServiceHistoryExplanationText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Il registro potrebbe non essere disponibile o accessibile.");
                ServiceHistoryList.ItemsSource = null;
            }
        }
        finally
        {
            if (string.Equals(_serviceEventsLoading, service.Name, StringComparison.OrdinalIgnoreCase))
                _serviceEventsLoading = null;
            _serviceEventsGate.Release();
        }
    }

    private void RenderServiceHistory(ServiceSnapshot service, ServiceHistoryResult result)
    {
        ServiceHistoryStatusText.Text = global::ProcessLens.Core.SysPulseLocalization.Concat(result.SourceStatus,(_serviceEventsWatcher?.Error is string err ? global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal(" · Monitoraggio live non disponibile: "),err) :
                global::ProcessLens.Core.SysPulseLocalization.Literal(" · Nuovi eventi aggiornati durante la vista Servizi")));
        ServiceHistoryExplanationText.Text = ServiceHistoryInterpretation.Explain(service, result.Events, result.Available);
        ServiceHistoryList.ItemsSource = result.Events;
    }

    private async void RefreshServiceHistory_Click(object sender, RoutedEventArgs e)
    {
        if (_selectedService is { } service)
            await LoadServiceHistoryAsync(service, force: true);
    }

    private string DescribeReverseDependencies(ServiceSnapshot service)
    {
        var dependent = _allServices.Where(x => x.IsRunning && x.Dependencies.Any(d =>
            d.Equals(service.Name, StringComparison.OrdinalIgnoreCase)))
            .Select(x => x.DisplayName).Take(15).ToList();
        return dependent.Count == 0 ? global::ProcessLens.Core.SysPulseLocalization.Literal("Nessuno rilevato nell'elenco corrente") : global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(", "),dependent);
    }

    private void ClearServiceDetails()
    {
        _selectedService = null;
        ServiceDetailName.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Seleziona un servizio");
        ServiceDetailIdentity.Text = "";
        ServiceDetailStatus.Text = "";
        ServiceDetailDescription.Text = "";
        ServiceDetailWhy.Text = "";
        ServiceDetailHost.Text = "";
        ServiceDetailDependencies.Text = "";
        ServiceDetailImpact.Text = "";
        ServiceDetailTechnical.Text = "";
        ServiceShowProcessButton.IsEnabled = false;
        ServiceStopButton.IsEnabled = false;
        ServiceHistoryRefreshButton.IsEnabled = false;
        ServiceHistoryStatusText.Text = global::ProcessLens.Core.SysPulseLocalization.Literal("Seleziona un servizio per vedere gli eventi Windows.");
        ServiceHistoryExplanationText.Text = "";
        ServiceHistoryList.ItemsSource = null;
        ++_serviceEventsRequest;
    }

    private void ServiceShowProcess_Click(object sender, RoutedEventArgs e)
    {
        if (_selectedService is { } service) NavigateToHostProcess(service);
    }

    private void NavigateToHostProcess(ServiceSnapshot service)
    {
        if (service.ProcessId <= 0 || !_allRows.Any(x => x.Pid == service.ProcessId)) return;
        // Only navigate: never terminate a shared service host implicitly.
        _activeFilter = global::ProcessLens.Core.SysPulseLocalization.Literal("Tutti");
        _selectedPid = service.ProcessId;
        SetFilterButtonState();
        SetServicesMode(false);
        SearchBox.Text = service.ProcessId.ToString();
        ApplyFilter(service.ProcessId);
    }

    private async void RefreshServices_Click(object sender, RoutedEventArgs e) => await RefreshServicesAsync(true);
    private void ServiceSort_SelectionChanged(object sender, SelectionChangedEventArgs e)
    {
        if (!IsLoaded) return;
        if (sender is ComboBox { SelectedItem: ComboBoxItem item } && item.Content is string mode)
            _serviceSortMode = mode;
        ApplyServiceFilter();
    }
    private void SetServiceFilter(string state)
    {
        _serviceFilter = state;
        ApplyServiceFilter();
    }
    private void ServiceFilterAll_Click(object sender, RoutedEventArgs e) => SetServiceFilter(global::ProcessLens.Core.SysPulseLocalization.Literal("Tutti"));
    private void ServiceFilterRunning_Click(object sender, RoutedEventArgs e) => SetServiceFilter(global::ProcessLens.Core.SysPulseLocalization.Literal("Attivi"));
    private void ServiceFilterStopped_Click(object sender, RoutedEventArgs e) => SetServiceFilter(global::ProcessLens.Core.SysPulseLocalization.Literal("Arrestati"));

}
